// Draw rocket
function drawRocket(x, y) {
    // Rocket body
    ctx.fillStyle = '#ff6666';
    ctx.fillRect(x, y, 10, 30);

    // Rocket fins
    ctx.fillStyle = '#cc3333';
    ctx.fillRect(x - 3, y + 25, 3, 8);
    ctx.fillRect(x + 10, y + 25, 3, 8);

    // Rocket nose
    ctx.fillStyle = '#ff3333';
    ctx.beginPath();
    ctx.moveTo(x + 5, y);
    ctx.lineTo(x, y + 8);
    ctx.lineTo(x + 10, y + 8);
    ctx.closePath();
    ctx.fill();

    // Rocket windows
    ctx.fillStyle = '#66ccff';
    ctx.fillRect(x + 2, y + 10, 6, 4);
}

// Draw flame
function drawFlame(x, y) {
    ctx.fillStyle = '#ff9900';
    ctx.beginPath();
    ctx.moveTo(x, y + 30);
    ctx.lineTo(x - 5, y + 40);
    ctx.lineTo(x + 15, y + 40);
    ctx.closePath();
    ctx.fill();

    ctx.fillStyle = '#ffff00';
    ctx.beginPath();
    ctx.moveTo(x, y + 30);
    ctx.lineTo(x - 3, y + 35);
    ctx.lineTo(x + 8, y + 35);
    ctx.closePath();
    ctx.fill();
}

// Animation
let rocketY = H - 50;
let flameHeight = 10;
let flameOffset = 0;

function animate() {
    // Clear canvas
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, W, H);

    // Redraw stars and ground
    ctx.fillStyle = '#fff';
    for (let i = 0; i < 100; i++) {
        const x = Math.random() * W;
        const y = Math.random() * H;
        const size = Math.random() * 2;
        ctx.fillRect(x, y, size, size);
    }

    ctx.fillStyle = '#555';
    ctx.fillRect(0, H - 20, W, 20);

    // Draw flame and rocket
    drawFlame(195, rocketY);
    drawRocket(195, rocketY);

    // Update positions
    rocketY -= 2;
    flameHeight = 10 + Math.sin(flameOffset) * 3;
    flameOffset += 0.3;

    // Reset rocket when it goes off screen
    if (rocketY < -50) {
        rocketY = H - 50;
    }

    requestAnimationFrame(animate);
}

