  // Flower center
  ctx.fillStyle = '#FFD700';
  ctx.fillRect(x-8, y-10, 16, 16);

  // Petals
  ctx.fillStyle = color;
  ctx.fillRect(x-12, y, 8, 8);
  ctx.fillRect(x+4, y, 8, 8);
  ctx.fillRect(x-4, y-12, 8, 8);
  ctx.fillRect(x-4, y+4, 8, 8);
}

