const drawStarfish = () => {
  // Sand background
  ctx.fillStyle = '#e6d2a5';
  ctx.fillRect(0, 0, W, H);

  // Sand details
  ctx.fillStyle = '#d4c192';
  for (let i = 0; i < 50; i++) {
    const x = Math.random() * W;
    const y = Math.random() * H;
    const size = Math.random() * 3;
    ctx.fillRect(x, y, size, size);
  }

  // Starfish body
  ctx.fillStyle = '#ff6b6b';
  ctx.beginPath();
  ctx.arc(200, 200, 40, 0, Math.PI * 2);
  ctx.fill();

  // Starfish arms
  ctx.fillStyle = '#ff8e8e';
  for (let i = 0; i < 5; i++) {
    const angle = (i * Math.PI * 2) / 5 - Math.PI / 2;
    const x1 = 200 + Math.cos(angle) * 40;
    const y1 = 200 + Math.sin(angle) * 40;
    const x2 = 200 + Math.cos(angle) * 70;
    const y2 = 200 + Math.sin(angle) * 70;

    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.lineTo(x2 - Math.cos(angle) * 15, y2 - Math.sin(angle) * 15);
    ctx.closePath();
    ctx.fill();
  }

  // Starfish eyes
  ctx.fillStyle = '#222';
  ctx.beginPath();
  ctx.arc(180, 180, 5, 0, Math.PI * 2);
  ctx.arc(220, 180, 5, 0, Math.PI * 2);
  ctx.fill();
};

