  ctx.fillStyle = '#333';
  ctx.fillRect(198, 250, 4, 10);

  // Draw flame
  const flameHeight = 30 + Math.random() * 20;
  const flameY = 240 - flameHeight;

  // Outer flame (yellow)
  ctx.fillStyle = '#ff9900';
  ctx.beginPath();
  ctx.arc(200, flameY, 8 + Math.random() * 5, 0, Math.PI * 2);
  ctx.fill();

  // Inner flame (white/yellow)
  ctx.fillStyle = '#ffff66';
  ctx.beginPath();
  ctx.arc(200, flameY - 2, 5 + Math.random() * 3, 0, Math.PI * 2);
  ctx.fill();
}

