}

function drawCandle() {
  // Draw candle base
  ctx.fillStyle = '#eee';
  ctx.fillRect(180, 250, 40, 100);

  // Draw candle wax
  ctx.fillStyle = '#fff';
  ctx.fillRect(185, 255, 30, 90);

  // Draw flame
  const flameHeight = 30 + Math.sin(Date.now() / 100) * 5;
  const flameY = 240 - flameHeight;

  // Flame core (yellow)
  ctx.fillStyle = '#ffff00';
  ctx.beginPath();
  ctx.arc(200, flameY, 8, 0, Math.PI * 2);
  ctx.fill();

  // Flame outer (orange)
  ctx.fillStyle = '#ff8800';
  ctx.beginPath();
  ctx.arc(200, flameY, 12, 0, Math.PI * 2);
  ctx.fill();

  // Flame highlight (white)
  ctx.fillStyle = '#ffffff';
  ctx.beginPath();
  ctx.arc(195, flameY - 2, 3, 0, Math.PI * 2);
  ctx.fill();
}

