function animate() {
    // Clear canvas
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, W, H);

    // Redraw stars
    ctx.fillStyle = '#fff';
    for (let i = 0; i < 100; i++) {
        const x = Math.random() * W;
        const y = Math.random() * H;
        const size = Math.random() * 2;
        ctx.fillRect(x, y, size, size);
    }

    // Redraw ground
    ctx.fillStyle = '#555';
    ctx.fillRect(0, H - 20, W, 20);

    // Update rocket position
    rocketY = H - 20 - (frame * 2);

    // Draw rocket body
    ctx.fillStyle = '#ff4444';
    ctx.fillRect(190, rocketY - 60, 20, 60);

    // Draw rocket nose
    ctx.fillStyle = '#ff6666';
    ctx.beginPath();
    ctx.moveTo(190, rocketY - 60);
    ctx.lineTo(200, rocketY - 70);
    ctx.lineTo(210, rocketY - 60);
    ctx.fill();

    // Draw rocket fins
    ctx.fillStyle = '#cc3333';
    ctx.fillRect(180, rocketY - 40, 10, 15);
    ctx.fillRect(210, rocketY - 40, 10, 15);

    // Draw flames
    ctx.fillStyle = '#ffff00';
    ctx.beginPath();
    ctx.moveTo(190, rocketY);
    ctx.lineTo(200, rocketY + 15);
    ctx.lineTo(210, rocketY);
    ctx.fill();

    // Draw flame effect
    if (frame % 2 === 0) {
        ctx.fillStyle = '#ff6600';
        ctx.beginPath();
        ctx.moveTo(195, rocketY);
        ctx.lineTo(200, rocketY + 20);
        ctx.lineTo(205, rocketY);
        ctx.fill();
    }

    // Continue animation
    frame++;
    if (rocketY > -100) {
        requestAnimationFrame(animate);
    }
}

