    drawRocket(200, rocketY);

    // Move rocket up
    if (launchCount < 100) {
        rocketY -= 2;
        launchCount++;
    }

    // Draw rocket trail
    if (launchCount > 20 && launchCount < 100) {
        ctx.fillStyle = `rgba(255, 150, 0, ${0.3 + Math.random() * 0.3})`;
        ctx.fillRect(195, rocketY + 30, 10, 10);
    }

    if (launchCount < 100) {
        requestAnimationFrame(animate);
    }
}

