    radius = 20 + i * 3;
    angle = i * 0.2;

    ctx.moveTo(200 + Math.cos(angle) * radius, 200 + Math.sin(angle) * radius);

    for (let j = i * 5; j < (i + 1) * 5; j++) {
        angle += 0.2;
        radius += 0.2;
        const x = 200 + Math.cos(angle) * radius;
        const y = 200 + Math.sin(angle) * radius;
        ctx.lineTo(x, y);
    }

    ctx.stroke();
}

