// Draw mushrooms
function drawMushroom(x, y, capColor, stemColor) {
    // Draw stem
    ctx.fillStyle = stemColor;
    ctx.fillRect(x - 4, y, 8, 20);

    // Draw cap
    ctx.fillStyle = capColor;
    ctx.beginPath();
    ctx.arc(x, y, 12, 0, Math.PI, true);
    ctx.fill();

    // Draw glow effect
    ctx.fillStyle = capColor.replace(/([0-9a-f])/g, (m, c) => {
        const val = parseInt(c, 16) + 4;
        return val > 15 ? 'f' : val.toString(16);
    });
    ctx.globalAlpha = 0.3;
    ctx.beginPath();
    ctx.arc(x, y, 14, 0, Math.PI, true);
    ctx.fill();
    ctx.globalAlpha = 1;
}

