const drawWerewolf = () => {
  // Background
  ctx.fillStyle = '#000';
  ctx.fillRect(0, 0, W, H);

  // Moon
  ctx.fillStyle = '#fff';
  ctx.beginPath();
  ctx.arc(320, 60, 30, 0, Math.PI * 2);
  ctx.fill();

  // Werewolf body
  ctx.fillStyle = '#222';
  ctx.fillRect(150, 200, 100, 150);

  // Werewolf head
  ctx.fillStyle = '#222';
  ctx.beginPath();
  ctx.arc(200, 150, 40, 0, Math.PI * 2);
  ctx.fill();

  // Werewolf ears
  ctx.fillStyle = '#222';
  ctx.beginPath();
  ctx.arc(180, 120, 15, 0, Math.PI * 2);
  ctx.arc(220, 120, 15, 0, Math.PI * 2);
  ctx.fill();

  // Werewolf eyes
  ctx.fillStyle = '#ff0';
  ctx.beginPath();
  ctx.arc(190, 140, 5, 0, Math.PI * 2);
  ctx.arc(210, 140, 5, 0, Math.PI * 2);
  ctx.fill();

  // Werewolf nose
  ctx.fillStyle = '#000';
  ctx.beginPath();
  ctx.arc(200, 160, 5, 0, Math.PI * 2);
  ctx.fill();

  // Werewolf mouth
  ctx.strokeStyle = '#000';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(200, 170, 10, 0, Math.PI);
  ctx.stroke();

  // Werewolf claws
  ctx.fillStyle = '#444';
  ctx.fillRect(130, 250, 20, 10);
  ctx.fillRect(120, 250, 10, 20);
  ctx.fillRect(240, 250, 20, 10);
  ctx.fillRect(250, 250, 10, 20);

  // Werewolf legs
  ctx.fillStyle = '#222';
  ctx.fillRect(140, 300, 20, 50);
  ctx.fillRect(210, 300, 20, 50);

  // Howling effect
  ctx.strokeStyle = '#fff';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(200, 120);
  ctx.lineTo(150, 80);
  ctx.lineTo(200, 80);
  ctx.lineTo(250, 80);
  ctx.lineTo(200, 120);
  ctx.stroke();

  // Additional howling lines
  ctx.beginPath();
  ctx.moveTo(180, 100);
  ctx.lineTo(140, 70);
  ctx.lineTo(180, 70);
  ctx.lineTo(220, 70);
  ctx.lineTo(180, 100);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(220, 100);
  ctx.lineTo(260, 70);
  ctx.lineTo(220, 70);
  ctx.lineTo(180, 70);
  ctx.lineTo(220, 100);
  ctx.stroke();
};

