// Create glowing lightsabers
function drawLightsaber(x, y, color, length, width) {
    // Blade glow
    const gradient = ctx.createLinearGradient(x, y, x, y + length);
    gradient.addColorStop(0, color);
    gradient.addColorStop(0.3, color);
    gradient.addColorStop(1, 'rgba(0,0,0,0)');

    ctx.fillStyle = gradient;
    ctx.fillRect(x - width/2, y, width, length);

    // Blade core
    ctx.fillStyle = color;
    ctx.fillRect(x - width/4, y, width/2, length);

    // Hilt
    ctx.fillStyle = '#333';
    ctx.fillRect(x - 15, y + length, 30, 10);

    // Hilt details
    ctx.fillStyle = '#666';
    ctx.fillRect(x - 10, y + length + 5, 20, 3);
}

