function drawPumpkin(x, y, size, color) {
    // Stem
    ctx.fillStyle = '#228B22';
    ctx.fillRect(x - 5, y - size/2, 10, size/4);

    // Pumpkin body
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.ellipse(x, y, size/2, size/1.5, 0, 0, Math.PI * 2);
    ctx.fill();

    // Face
    ctx.fillStyle = '#000';
    // Eyes
    ctx.beginPath();
    ctx.arc(x - size/4, y - size/6, size/8, 0, Math.PI * 2);
    ctx.arc(x + size/4, y - size/6, size/8, 0, Math.PI * 2);
    ctx.fill();

    // Mouth
    ctx.beginPath();
    ctx.arc(x, y + size/6, size/4, 0, Math.PI);
    ctx.stroke();
}

