// Draw multiple pumpkins
function drawPumpkin(x, y, size) {
    // Pumpkin body
    ctx.fillStyle = '#FF8C00';
    ctx.beginPath();
    ctx.ellipse(x, y, size, size * 0.7, 0, 0, Math.PI * 2);
    ctx.fill();

    // Pumpkin stem
    ctx.fillStyle = '#228B22';
    ctx.fillRect(x - size * 0.1, y - size * 0.8, size * 0.2, size * 0.3);

    // Pumpkin face
    ctx.fillStyle = '#000';
    // Eyes
    ctx.beginPath();
    ctx.arc(x - size * 0.3, y - size * 0.2, size * 0.1, 0, Math.PI * 2);
    ctx.arc(x + size * 0.3, y - size * 0.2, size * 0.1, 0, Math.PI * 2);
    ctx.fill();

    // Nose
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(x - size * 0.1, y + size * 0.2);
    ctx.lineTo(x + size * 0.1, y + size * 0.2);
    ctx.closePath();
    ctx.fill();

    // Mouth
    ctx.beginPath();
    ctx.arc(x, y + size * 0.3, size * 0.2, 0, Math.PI);
    ctx.stroke();
}

