const drawHedgehogBall = () => {
  // Background
  ctx.fillStyle = '#87CEEB';
  ctx.fillRect(0, 0, W, H);

  // Ground
  ctx.fillStyle = '#8B4513';
  ctx.fillRect(0, 350, W, 50);

  // Hedgehog ball body
  ctx.fillStyle = '#228B22';
  ctx.beginPath();
  ctx.arc(200, 250, 60, 0, Math.PI * 2);
  ctx.fill();

  // Spikes
  ctx.strokeStyle = '#228B22';
  ctx.lineWidth = 3;
  for (let i = 0; i < 12; i++) {
    const angle = (i / 12) * Math.PI * 2;
    const x = 200 + Math.cos(angle) * 60;
    const y = 250 + Math.sin(angle) * 60;
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(x + Math.cos(angle) * 15, y + Math.sin(angle) * 15);
    ctx.stroke();
  }

  // Eyes
  ctx.fillStyle = '#000';
  ctx.beginPath();
  ctx.arc(180, 240, 5, 0, Math.PI * 2);
  ctx.arc(220, 240, 5, 0, Math.PI * 2);
  ctx.fill();

  // Nose
  ctx.fillStyle = '#000';
  ctx.beginPath();
  ctx.arc(200, 260, 3, 0, Math.PI * 2);
  ctx.fill();

  // Mouth
  ctx.strokeStyle = '#000';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.arc(200, 265, 5, 0, Math.PI);
  ctx.stroke();
};

drawHedgehogBall();

