function drawCandle() {
  // Draw flame
  const time = Date.now() / 100;
  const flicker = Math.sin(time) * 10 + Math.sin(time * 2) * 5;

  // Flame base
  ctx.fillStyle = '#ff9900';
  ctx.fillRect(190, 120, 20, 40);

  // Flame tip
  ctx.fillStyle = '#ffff00';
  const flameHeight = 30 + flicker;
  ctx.beginPath();
  ctx.moveTo(190, 120);
  ctx.lineTo(210, 120);
  ctx.lineTo(200, 120 - flameHeight);
  ctx.closePath();
  ctx.fill();

  // Inner flame
  ctx.fillStyle = '#ff5500';
  const innerFlameHeight = 20 + flicker * 0.5;
  ctx.beginPath();
  ctx.moveTo(195, 120);
  ctx.lineTo(205, 120);
  ctx.lineTo(200, 120 - innerFlameHeight);
  ctx.closePath();
  ctx.fill();

  // Wick
  ctx.fillStyle = '#000';
  ctx.fillRect(200, 115, 2, 5);

  // Candle body
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(180, 160, 40, 100);

  // Wax drips
  ctx.fillStyle = '#f0f0f0';
  ctx.fillRect(175, 170, 5, 10);
  ctx.fillRect(220, 180, 5, 15);
  ctx.fillRect(185, 200, 5, 8);
}

