function drawFlame() {
  // Clear previous flame
  ctx.fillStyle = '#000';
  ctx.fillRect(195, 130, 10, 20);

  // Draw flickering flame
  const flameColors = ['#ff9900', '#ff6600', '#ff3300', '#ffcc00'];
  const color = flameColors[Math.floor(Math.random() * flameColors.length)];

  ctx.fillStyle = color;
  const size = 8 + Math.random() * 6;
  const x = 195 + Math.random() * 4;
  const y = 130 + Math.random() * 8;

  ctx.beginPath();
  ctx.arc(x, y, size, 0, Math.PI * 2);
  ctx.fill();

  // Draw glow
  ctx.fillStyle = '#ffff66';
  ctx.beginPath();
  ctx.arc(x, y, size * 0.7, 0, Math.PI * 2);
  ctx.fill();
}

