function drawSparkle(x, y) {
    ctx.fillStyle = '#FFD700';
    ctx.fillRect(x, y, 2, 2);
    ctx.fillRect(x-1, y-1, 2, 2);
    ctx.fillRect(x+1, y+1, 2, 2);
    ctx.fillRect(x-1, y+1, 2, 2);
    ctx.fillRect(x+1, y-1, 2, 2);
}

