  ctx.moveTo(x - 5, y + 3);
  ctx.lineTo(x - 10, y + 9);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(x + 5, y + 2);
  ctx.lineTo(x + 10, y + 8);
