function drawBee(x, y) {
    // Body
    ctx.fillStyle = '#FFD700';
    ctx.fillRect(x, y, 15, 8);

    // Wings
    ctx.fillStyle = '#E0E0E0';
    ctx.fillRect(x+5, y-3, 10, 5);
    ctx.fillRect(x+5, y+8, 10, 5);

    // Eyes
    ctx.fillStyle = '#000';
    ctx.fillRect(x+12, y+2, 2, 2);
    ctx.fillRect(x+10, y+2, 2, 2);

    // Antennae
    ctx.strokeStyle = '#000';
    ctx.beginPath();
    ctx.moveTo(x+13, y+1);
    ctx.lineTo(x+15, y-1);
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(x+11, y+1);
    ctx.lineTo(x+9, y-1);
    ctx.stroke();
}

