  // Draw logs
  ctx.fillStyle = '#553';
  ctx.fillRect(W/2 - 60, H * 0.75, 120, 20);
  ctx.fillRect(W/2 - 40, H * 0.73, 80, 15);
  ctx.fillRect(W/2 - 20, H * 0.71, 40, 10);

