  ctx.fillRect(W/2 - 25, H * 0.68, 50, 25);

  ctx.fillStyle = '#ff0';
  ctx.fillRect(W/2 - 15, H * 0.65, 30, 20);

  // Draw smoke
  ctx.fillStyle = '#aaa';
  ctx.fillRect(W/2 - 10, H * 0.6, 20, 15);
  ctx.fillRect(W/2 - 15, H * 0.55, 30, 12);
  ctx.fillRect(W/2 - 20, H * 0.5, 40, 10);

  // Draw sparks
  ctx.fillStyle = '#ff0';
  for (let i = 0; i < 20; i++) {
    const x = W/2 + Math.random() * 30 - 15;
    const y = H * 0.5 - Math.random() * 30;
    const size = Math.random() * 3;
    ctx.fillRect(x, y, size, size);
  }
};

