function drawRocket(x, y) {
    // Rocket body
    ctx.fillStyle = '#ff6666';
    ctx.fillRect(x, y, 20, 60);

    // Rocket nose
    ctx.fillStyle = '#ff3333';
    ctx.beginPath();
    ctx.moveTo(x + 10, y);
    ctx.lineTo(x + 20, y + 15);
    ctx.lineTo(x, y + 15);
    ctx.closePath();
    ctx.fill();

    // Rocket fins
    ctx.fillStyle = '#cc3333';
    ctx.fillRect(x - 5, y + 40, 5, 15);
    ctx.fillRect(x + 20, y + 40, 5, 15);

    // Rocket window
    ctx.fillStyle = '#66ccff';
    ctx.fillRect(x + 7, y + 20, 6, 8);
}

// Draw flames
function drawFlame(x, y) {
    ctx.fillStyle = '#ff9900';
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(x + 20, y);
    ctx.lineTo(x + 10, y + 20);
    ctx.closePath();
    ctx.fill();

    ctx.fillStyle = '#ff6600';
    ctx.beginPath();
    ctx.moveTo(x + 5, y);
    ctx.lineTo(x + 15, y);
    ctx.lineTo(x + 10, y + 15);
    ctx.closePath();
    ctx.fill();
}

// Animation
let rocketY = H - 100;
let flameHeight = 20;
let counter = 0;

function animate() {
    // Clear canvas
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, W, H);

    // Redraw stars
    ctx.fillStyle = '#fff';
    for (let i = 0; i < 100; i++) {
        const x = Math.random() * W;
        const y = Math.random() * H;
        const size = Math.random() * 2;
        ctx.fillRect(x, y, size, size);
    }

    // Draw ground
    ctx.fillStyle = '#555';
    ctx.fillRect(0, H - 20, W, 20);

    // Update rocket position
    rocketY -= 2;
    counter++;

    // Draw rocket
    drawRocket(190, rocketY);

    // Draw flames
    if (counter % 3 === 0) {
        flameHeight = 15 + Math.random() * 10;
    }
    drawFlame(190, rocketY + 60);

    // Keep launching until rocket is off screen
    if (rocketY > -100) {
        requestAnimationFrame(animate);
    }
}

