// Animation loop
function animate() {
    // Clear canvas
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, W, H);

    // Redraw stars
    ctx.fillStyle = '#fff';
    for (let i = 0; i < 100; i++) {
        const x = Math.random() * W;
        const y = Math.random() * H;
        const size = Math.random() * 2;
        ctx.fillRect(x, y, size, size);
    }

    // Draw ground
    ctx.fillStyle = '#555';
    ctx.fillRect(0, H - 20, W, 20);

    // Update rocket position
    rocketY -= 2;
    flameHeight = 10 + Math.sin(Date.now() / 100) * 5;

    // Draw rocket body
    ctx.fillStyle = '#f00';
    ctx.fillRect(190, rocketY, 20, 40);

    // Draw rocket nose
    ctx.fillStyle = '#ff0000';
    ctx.beginPath();
    ctx.moveTo(190, rocketY);
    ctx.lineTo(210, rocketY);
    ctx.lineTo(200, rocketY - 10);
    ctx.closePath();
    ctx.fill();

    // Draw rocket fins
    ctx.fillStyle = '#ff0000';
    ctx.fillRect(185, rocketY + 20, 5, 10);
    ctx.fillRect(215, rocketY + 20, 5, 10);

    // Draw flame
    ctx.fillStyle = '#ff9900';
    ctx.beginPath();
    ctx.moveTo(200, rocketY + 40);
    ctx.lineTo(190, rocketY + 40 + flameHeight);
    ctx.lineTo(210, rocketY + 40 + flameHeight);
    ctx.closePath();
    ctx.fill();

    // Draw flame glow
    ctx.fillStyle = '#ffff00';
    ctx.beginPath();
    ctx.moveTo(200, rocketY + 40);
    ctx.lineTo(195, rocketY + 40 + flameHeight * 0.7);
    ctx.lineTo(205, rocketY + 40 + flameHeight * 0.7);
    ctx.closePath();
    ctx.fill();

    // Stop animation when rocket leaves screen
    if (rocketY < -50) {
        return;
    }

    requestAnimationFrame(animate);
}

