// Starfish
ctx.fillStyle = '#d44';
const centerX = 200;
const centerY = 250;
const arms = 5;
const armLength = 30;

// Body
ctx.beginPath();
ctx.arc(centerX, centerY, 15, 0, Math.PI * 2);
ctx.fill();

// Arms
for(let i = 0; i < arms; i++) {
  const angle = (i * Math.PI * 2) / arms - Math.PI/2;
  const startX = centerX + Math.cos(angle) * 15;
  const startY = centerY + Math.sin(angle) * 15;
  const endX = centerX + Math.cos(angle) * (15 + armLength);
  const endY = centerY + Math.sin(angle) * (15 + armLength);

  ctx.beginPath();
  ctx.moveTo(startX, startY);
  ctx.lineTo(endX, endY);
  ctx.lineWidth = 4;
  ctx.strokeStyle = '#d44';
  ctx.stroke();

  // Arm tip
  ctx.beginPath();
  ctx.arc(endX, endY, 6, 0, Math.PI * 2);
  ctx.fillStyle = '#d44';
  ctx.fill();
}

