const drawClown = () => {
  // Background
  ctx.fillStyle = '#87CEEB';
  ctx.fillRect(0, 0, W, H);

  // Ground
  ctx.fillStyle = '#8B4513';
  ctx.fillRect(0, 350, W, 50);

  // Clown body
  ctx.fillStyle = '#FF69B4';
  ctx.fillRect(150, 200, 100, 150);

  // Clown head
  ctx.fillStyle = '#FFD700';
  ctx.beginPath();
  ctx.arc(200, 150, 60, 0, Math.PI * 2);
  ctx.fill();

  // Clown eyes
  ctx.fillStyle = '#000';
  ctx.beginPath();
  ctx.arc(180, 140, 8, 0, Math.PI * 2);
  ctx.arc(220, 140, 8, 0, Math.PI * 2);
  ctx.fill();

  // Clown nose
  ctx.fillStyle = '#FF69B4';
  ctx.beginPath();
  ctx.arc(200, 160, 15, 0, Math.PI * 2);
  ctx.fill();

  // Clown mouth
  ctx.strokeStyle = '#000';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(200, 190, 20, 0, Math.PI);
  ctx.stroke();

  // Clown arms
  ctx.fillStyle = '#FF69B4';
  ctx.fillRect(120, 220, 30, 80);
  ctx.fillRect(250, 220, 30, 80);

  // Clown legs
  ctx.fillStyle = '#1E90FF';
  ctx.fillRect(160, 350, 30, 50);
  ctx.fillRect(210, 350, 30, 50);

  // Balloons
  ctx.strokeStyle = '#FF0000';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(100, 250, 30, 0, Math.PI * 2);
  ctx.stroke();

  ctx.fillStyle = '#FF0000';
  ctx.fill();

  ctx.beginPath();
  ctx.arc(100, 250, 20, 0, Math.PI * 2);
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(100, 250, 10, 0, Math.PI * 2);
  ctx.fill();

  // Balloon string
  ctx.strokeStyle = '#000';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(100, 280);
  ctx.lineTo(100, 350);
  ctx.stroke();

  // Another balloon
  ctx.beginPath();
  ctx.arc(300, 200, 30, 0, Math.PI * 2);
  ctx.stroke();

  ctx.fillStyle = '#00FF00';
  ctx.fill();

  ctx.beginPath();
  ctx.arc(300, 200, 20, 0, Math.PI * 2);
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(300, 200, 10, 0, Math.PI * 2);
  ctx.fill();

  // Second balloon string
  ctx.beginPath();
  ctx.moveTo(300, 230);
  ctx.lineTo(300, 350);
  ctx.stroke();
};

