      // Upward triangle
      ctx.moveTo(x * triangleSize, y * triangleSize);
      ctx.lineTo((x + 1) * triangleSize, y * triangleSize);
      ctx.lineTo(x * triangleSize + triangleSize/2, (y + 1) * triangleSize);
