      // Downward triangle
      ctx.moveTo(x * triangleSize, (y + 1) * triangleSize);
      ctx.lineTo((x + 1) * triangleSize, (y + 1) * triangleSize);
      ctx.lineTo(x * triangleSize + triangleSize/2, y * triangleSize);
