// Falling leaves
function drawLeaf(x, y, size, color) {
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.ellipse(x, y, size, size/2, 0, 0, Math.PI * 2);
    ctx.fill();

    // Leaf stem
    ctx.strokeStyle = '#8B4513';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(x, y + size/2);
    ctx.lineTo(x, y + size);
    ctx.stroke();
}

// Draw leaves with varying positions and colors
