}

// Leaves
const leaves = [];
for (let i = 0; i < 50; i++) {
    leaves.push({
        x: Math.random() * W,
        y: Math.random() * H,
        size: 3 + Math.random() * 4,
        speed: 0.5 + Math.random() * 1.5,
        wind: (Math.random() - 0.5) * 0.5,
        rotation: Math.random() * Math.PI * 2,
        rotationSpeed: (Math.random() - 0.5) * 0.1
    });
}

// Animation loop
function animate() {
    // Clear canvas with sky
    ctx.fillStyle = '#87CEEB';
    ctx.fillRect(0, 0, W, H);

    // Draw ground
    ctx.fillStyle = '#8B4513';
    ctx.fillRect(0, 300, W, 100);

    // Draw wind lines
    ctx.strokeStyle = '#FFFFFF';
    ctx.lineWidth = 1;
    for (let i = 0; i < 20; i++) {
        const x = Math.random() * W;
        const y = Math.random() * 300;
        const length = 20 + Math.random() * 30;
        const angle = Math.random() * Math.PI / 4 - Math.PI / 8;

        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.lineTo(x + Math.cos(angle) * length, y + Math.sin(angle) * length);
        ctx.stroke();
    }

    // Draw leaves
    leaves.forEach(leaf => {
        // Update position
        leaf.y += leaf.speed;
        leaf.x += leaf.wind;
        leaf.rotation += leaf.rotationSpeed;

        // Reset if leaf goes off screen
        if (leaf.y > H) {
            leaf.y = -10;
            leaf.x = Math.random() * W;
        }

        // Draw leaf
        ctx.save();
        ctx.translate(leaf.x, leaf.y);
        ctx.rotate(leaf.rotation);

        // Leaf body
        ctx.fillStyle = '#FF6B35';
        ctx.beginPath();
        ctx.ellipse(0, 0, leaf.size, leaf.size * 1.5, 0, 0, Math.PI * 2);
        ctx.fill();

        // Leaf stem
        ctx.strokeStyle = '#8B4513';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(0, leaf.size * 0.5);
        ctx.lineTo(0, leaf.size * 1.5);
        ctx.stroke();

        ctx.restore();
    });

    requestAnimationFrame(animate);
}

