// Firework burst
function drawFirework(x, y, color) {
    ctx.fillStyle = color;
    // Central burst
    ctx.beginPath();
    ctx.arc(x, y, 3, 0, Math.PI * 2);
    ctx.fill();

    // Spikes
    for (let i = 0; i < 8; i++) {
        const angle = (i / 8) * Math.PI * 2;
        const endX = x + Math.cos(angle) * 15;
        const endY = y + Math.sin(angle) * 15;
        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.lineTo(endX, endY);
        ctx.stroke();
    }
}

