// Flowers
function drawFlower(x, y, color) {
    // Stem
    ctx.fillStyle = '#228B22';
    ctx.fillRect(x - 2, y, 4, 50);

    // Flower center
    ctx.fillStyle = '#FFA500';
    ctx.beginPath();
    ctx.arc(x, y - 10, 8, 0, Math.PI * 2);
    ctx.fill();

    // Petals
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.arc(x - 10, y - 15, 8, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.arc(x + 10, y - 15, 8, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.arc(x, y - 25, 8, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.arc(x, y - 5, 8, 0, Math.PI * 2);
    ctx.fill();
}

