// Bees
function drawBee(x, y) {
    // Body
    ctx.fillStyle = '#FFD700';
    ctx.fillRect(x - 5, y - 5, 10, 15);

    // Wings
    ctx.fillStyle = '#E0E0E0';
    ctx.beginPath();
    ctx.ellipse(x, y - 2, 8, 3, 0, 0, Math.PI * 2);
    ctx.fill();

    // Head
    ctx.fillStyle = '#000000';
    ctx.beginPath();
    ctx.arc(x, y - 12, 4, 0, Math.PI * 2);
    ctx.fill();

    // Eyes
    ctx.fillStyle = '#FFFFFF';
    ctx.beginPath();
    ctx.arc(x - 2, y - 14, 1, 0, Math.PI * 2);
    ctx.arc(x + 2, y - 14, 1, 0, Math.PI * 2);
    ctx.fill();
}

