const boardSize = 8 * squareSize;
const offsetX = (W - boardSize) / 2;
const offsetY = (H - boardSize) / 2;

// Draw squares
for (let row = 0; row < 8; row++) {
    for (let col = 0; col < 8; col++) {
        const x = offsetX + col * squareSize;
        const y = offsetY + row * squareSize;
        if ((row + col) % 2 === 0) {
            ctx.fillStyle = '#F0D9B5'; // Light square
        } else {
            ctx.fillStyle = '#B58863'; // Dark square
        }
        ctx.fillRect(x, y, squareSize, squareSize);
    }
}

