// Mushrooms with glowing caps
function drawMushroom(x, y, capColor, stemColor, glowColor) {
    // Stem
    ctx.fillStyle = stemColor;
    ctx.fillRect(x - 5, y, 10, 20);

    // Cap
    ctx.fillStyle = capColor;
    ctx.beginPath();
    ctx.arc(x, y, 15, 0, Math.PI, false);
    ctx.fill();

    // Glow
    ctx.fillStyle = glowColor;
    ctx.globalAlpha = 0.3;
    ctx.beginPath();
    ctx.arc(x, y, 18, 0, Math.PI, false);
    ctx.fill();
    ctx.globalAlpha = 1;
}

