    const angle = (i / tentacleCount) * Math.PI * 2;
    const startX = centerX + Math.cos(angle) * bodyRadius;
    const startY = centerY + Math.sin(angle) * bodyRadius;

    // Tentacle color (various pastel colors)
    const colors = ['#ff6b9d', '#ff8da8', '#ffb3c6', '#ffd1e0', '#ff99b3', '#ff6699', '#ff4080', '#ff1a66'];
    ctx.fillStyle = colors[i % colors.length];

    // Draw the tentacle
    ctx.beginPath();
    ctx.moveTo(startX, startY);

    // Make the tentacles wavy
    for (let j = 0; j < 5; j++) {
        const waveX = Math.sin(j * 0.5 + i) * 10;
        const waveY = j * 20;
        ctx.lineTo(startX + waveX, startY + waveY);
    }

    // End with a point
    ctx.lineTo(startX, startY + tentacleLength);
    ctx.fill();

    // Add some glow effect to tentacles
    ctx.strokeStyle = colors[i % colors.length] + '40';
    ctx.lineWidth = 3;
    ctx.stroke();
}

