const centerX = 200;
const centerY = 300;
const maxRadius = 150;
const spiralTurns = 8;
const colors = ['#2c1810', '#4a2c1c', '#6b4a3a', '#8c6a5a'];

for (let i = 0; i < 100; i++) {
    const radius = maxRadius * (1 - i/100);
    const angle = i * spiralTurns * Math.PI / 5;
    const x = centerX + Math.cos(angle) * radius;
    const y = centerY - Math.sin(angle) * radius;
    const size = Math.max(1, 10 - i/5);

    ctx.fillStyle = colors[Math.floor(i/25) % colors.length];
    ctx.beginPath();
    ctx.arc(x, y, size, 0, Math.PI * 2);
    ctx.fill();
}

