const centerX = 200;
const centerY = 300;
const maxRadius = 150;
const spiralTurns = 8;
const segments = 200;

ctx.strokeStyle = '#333333';
ctx.lineWidth = 3;

for (let i = 0; i < segments; i++) {
    const angle = (i / segments) * spiralTurns * Math.PI * 2;
    const radius = maxRadius * (1 - i / segments);
    const x = centerX + Math.cos(angle) * radius;
    const y = centerY - Math.sin(angle) * radius;

    if (i === 0) {
        ctx.beginPath();
        ctx.moveTo(x, y);
    } else {
        ctx.lineTo(x, y);
    }
}
ctx.stroke();

