// Flame
function drawFlame() {
    const time = Date.now() / 100;
    const flicker = Math.sin(time) * 10 + Math.sin(time * 2) * 5;

    // Main flame
    const gradient = ctx.createRadialGradient(200, 180, 0, 200, 180, 20);
    gradient.addColorStop(0, '#ffff00');
    gradient.addColorStop(0.5, '#ff8c00');
    gradient.addColorStop(1, '#ff4500');

    ctx.fillStyle = gradient;
    ctx.beginPath();
    ctx.ellipse(200, 180, 15 + flicker, 30 + flicker/2, 0, 0, Math.PI * 2);
    ctx.fill();

    // Inner flame
    const innerGradient = ctx.createRadialGradient(200, 180, 0, 200, 180, 10);
    innerGradient.addColorStop(0, '#ffffff');
    innerGradient.addColorStop(1, '#ffff00');

    ctx.fillStyle = innerGradient;
    ctx.beginPath();
    ctx.ellipse(200, 180, 8 + flicker/2, 15 + flicker/4, 0, 0, Math.PI * 2);
    ctx.fill();

    // Glow
    ctx.fillStyle = 'rgba(255, 140, 0, 0.2)';
    ctx.beginPath();
    ctx.ellipse(200, 180, 25 + flicker, 40 + flicker/2, 0, 0, Math.PI * 2);
    ctx.fill();
}

