// Draw butterfly wings
function drawWing(x, y, width, height, color, patternColor) {
    // Wing shape
    ctx.beginPath();
    ctx.ellipse(x, y, width, height, 0, 0, Math.PI * 2);
    ctx.fillStyle = color;
    ctx.fill();

    // Pattern on wing
    ctx.beginPath();
    ctx.ellipse(x, y, width * 0.8, height * 0.8, 0, 0, Math.PI * 2);
    ctx.fillStyle = patternColor;
    ctx.fill();

    // Add eye spots
    ctx.beginPath();
    ctx.arc(x + width * 0.3, y - height * 0.2, width * 0.25, 0, Math.PI * 2);
    ctx.fillStyle = '#000';
    ctx.fill();

    ctx.beginPath();
    ctx.arc(x + width * 0.3, y - height * 0.2, width * 0.1, 0, Math.PI * 2);
    ctx.fillStyle = '#FFF';
    ctx.fill();
}

