const shadowColors = ['#e85a5a', '#3db8b0', '#39a5c0', '#85c8a5', '#f5b03e'];

for (let i = 0; i < recordCount; i++) {
    const x = baseX - i * 5;
    const y = baseY - i * 15;
    const radius = 60 - i * 5;

    // Shadow
    ctx.fillStyle = shadowColors[i];
    ctx.beginPath();
    ctx.ellipse(x + 5, y + 5, radius, radius * 0.4, 0, 0, Math.PI * 2);
    ctx.fill();

    // Record
    ctx.fillStyle = colors[i];
    ctx.beginPath();
    ctx.ellipse(x, y, radius, radius, 0, 0, Math.PI * 2);
    ctx.fill();

    // Grooves
    ctx.strokeStyle = '#000';
    ctx.lineWidth = 0.5;
    ctx.beginPath();
    ctx.arc(x, y, radius - 5, 0, Math.PI * 2);
    ctx.stroke();

    for (let j = 0; j < 12; j++) {
        const angle = (j / 12) * Math.PI * 2;
        const grooveX = x + Math.cos(angle) * (radius - 10);
        const grooveY = y + Math.sin(angle) * (radius - 10);
        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.lineTo(grooveX, grooveY);
        ctx.stroke();
    }

    // Center label
    ctx.fillStyle = '#fff';
    ctx.beginPath();
    ctx.arc(x, y, 12, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = '#000';
    ctx.font = '12px Arial';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('LP', x, y);

