    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.arc(x, y, 18, 0, Math.PI * 2);
    ctx.fill();

    // Draw piece details
    ctx.fillStyle = color === '#000000' ? '#FFFFFF' : '#000000';
    if (type === 'king') {
        ctx.fillRect(x - 8, y - 20, 16, 8);
        ctx.fillRect(x - 12, y - 12, 24, 8);
    } else if (type === 'queen') {
        ctx.beginPath();
        ctx.arc(x, y - 15, 8, 0, Math.PI * 2);
        ctx.fill();
    } else if (type === 'rook') {
        ctx.fillRect(x - 15, y - 15, 30, 10);
        ctx.fillRect(x - 10, y - 25, 20, 10);
    } else if (type === 'bishop') {
        ctx.beginPath();
        ctx.moveTo(x, y - 20);
        ctx.lineTo(x - 15, y);
        ctx.lineTo(x + 15, y);
        ctx.closePath();
        ctx.fill();
    } else if (type === 'knight') {
        ctx.fillRect(x - 10, y - 15, 20, 10);
        ctx.fillRect(x - 15, y - 5, 10, 10);
    } else if (type === 'pawn') {
        ctx.fillRect(x - 8, y - 15, 16, 10);
    }
};

