// Create a colorful kaleidoscope pattern
function drawKaleidoscope() {
    // Clear canvas with a dark background
    ctx.fillStyle = '#0a0a2a';
    ctx.fillRect(0, 0, W, H);

    // Center coordinates
    const centerX = W / 2;
    const centerY = H / 2;

    // Draw multiple layers of triangles
    const layers = 8;
    const maxRadius = Math.min(W, H) * 0.4;

    for (let layer = 0; layer < layers; layer++) {
        const radius = maxRadius * (layer + 1) / layers;
        const segments = 12 + layer * 2;

        for (let i = 0; i < segments; i++) {
            const angle1 = (i / segments) * Math.PI * 2;
            const angle2 = ((i + 1) / segments) * Math.PI * 2;

            // Create triangle points
            const x1 = centerX + Math.cos(angle1) * radius;
            const y1 = centerY + Math.sin(angle1) * radius;
            const x2 = centerX + Math.cos(angle2) * radius;
            const y2 = centerY + Math.sin(angle2) * radius;

            // Color based on position and layer
            const hue = (i * 30 + layer * 20) % 360;
            const saturation = 80 + Math.sin(layer) * 20;
            const lightness = 40 + Math.cos(layer) * 20;

            ctx.fillStyle = `hsl(${hue}, ${saturation}%, ${lightness}%)`;

            // Draw triangle
            ctx.beginPath();
            ctx.moveTo(centerX, centerY);
            ctx.lineTo(x1, y1);
            ctx.lineTo(x2, y2);
            ctx.closePath();
            ctx.fill();
        }
    }

    // Add central circular pattern
    const centerRadius = 20;
    for (let i = 0; i < 12; i++) {
        const angle = (i / 12) * Math.PI * 2;
        const x = centerX + Math.cos(angle) * centerRadius;
        const y = centerY + Math.sin(angle) * centerRadius;

        const hue = (i * 30) % 360;
        ctx.fillStyle = `hsl(${hue}, 90%, 60%)`;
        ctx.beginPath();
        ctx.arc(x, y, 8, 0, Math.PI * 2);
        ctx.fill();
    }
}

