// Create a colorful kaleidoscope pattern
function drawKaleidoscope() {
    // Clear canvas with dark background
    ctx.fillStyle = '#0a0a2a';
    ctx.fillRect(0, 0, W, H);

    // Center point
    const cx = W / 2;
    const cy = H / 2;

    // Draw radial symmetry pattern
    const numSectors = 12;
    const maxRadius = Math.min(W, H) * 0.4;

    // Draw concentric circles
    for (let r = 20; r < maxRadius; r += 20) {
        ctx.beginPath();
        ctx.arc(cx, cy, r, 0, Math.PI * 2);
        ctx.strokeStyle = `hsl(${(r * 3) % 360}, 70%, 50%)`;
        ctx.lineWidth = 2;
        ctx.stroke();
    }

    // Draw radial lines
    for (let i = 0; i < numSectors; i++) {
        const angle = (i / numSectors) * Math.PI * 2;
        const x1 = cx + Math.cos(angle) * 10;
        const y1 = cy + Math.sin(angle) * 10;
        const x2 = cx + Math.cos(angle) * maxRadius;
        const y2 = cy + Math.sin(angle) * maxRadius;

        ctx.beginPath();
        ctx.moveTo(x1, y1);
        ctx.lineTo(x2, y2);
        ctx.strokeStyle = `hsla(${(i * 30) % 360}, 80%, 60%, 0.7)`;
        ctx.lineWidth = 1;
        ctx.stroke();
    }

    // Draw colorful triangles
    const triangleSize = 30;
    for (let i = 0; i < 200; i++) {
        const angle = (i * 0.1) % (Math.PI * 2);
        const radius = (i * 5) % (maxRadius * 0.8);
        const x = cx + Math.cos(angle) * radius;
        const y = cy + Math.sin(angle) * radius;

        // Create triangle pattern
        const triangleAngle = (i * 0.3) % (Math.PI * 2);
        const dx = Math.cos(triangleAngle) * triangleSize;
        const dy = Math.sin(triangleAngle) * triangleSize;

        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.lineTo(x + dx, y + dy);
        ctx.lineTo(x - dy, y + dx);
        ctx.closePath();

        const hue = (i * 10) % 360;
        ctx.fillStyle = `hsla(${hue}, 80%, 60%, 0.6)`;
        ctx.fill();
    }

    // Add central orb
    const orbRadius = 20;
    ctx.beginPath();
    ctx.arc(cx, cy, orbRadius, 0, Math.PI * 2);
    const gradient = ctx.createRadialGradient(cx, cy, 0, cx, cy, orbRadius);
    gradient.addColorStop(0, '#ffffff');
    gradient.addColorStop(1, '#ff6600');
    ctx.fillStyle = gradient;
    ctx.fill();

    // Add glow effect
    ctx.beginPath();
    ctx.arc(cx, cy, orbRadius + 5, 0, Math.PI * 2);
    const glowGradient = ctx.createRadialGradient(cx, cy, orbRadius, cx, cy, orbRadius + 10);
    glowGradient.addColorStop(0, 'rgba(255, 102, 0, 0.5)');
    glowGradient.addColorStop(1, 'rgba(255, 102, 0, 0)');
    ctx.fillStyle = glowGradient;
    ctx.fill();
}

