// Tornado spiral
const centerX = 200;
const centerY = 250;
const maxRadius = 150;
const spiralWidth = 20;
const colors = ['#000000', '#222222', '#444444', '#666666'];

for (let i = 0; i < 20; i++) {
    const radius = maxRadius - (i * 7);
    const angle = i * 0.5;

    ctx.beginPath();
    ctx.arc(centerX, centerY, radius, angle, angle + Math.PI/2);

    // Create spiral effect with gradient
    const gradient = ctx.createLinearGradient(
        centerX - radius, centerY - radius,
        centerX + radius, centerY + radius
    );

    gradient.addColorStop(0, colors[i % colors.length]);
    gradient.addColorStop(1, colors[(i+1) % colors.length]);

    ctx.strokeStyle = gradient;
    ctx.lineWidth = spiralWidth - (i * 0.8);
    ctx.lineCap = 'round';
    ctx.stroke();
}

