// Pine trees
function drawPine(x, y, size, color) {
    // Trunk
    ctx.fillStyle = '#5d4037';
    ctx.fillRect(x - size/6, y, size/3, size/2);

    // Tree
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(x - size/2, y);
    ctx.lineTo(x, y - size);
    ctx.lineTo(x + size/2, y);
    ctx.closePath();
    ctx.fill();

    // Additional layers for depth
    ctx.fillStyle = color.replace('3a', '2a');
    ctx.beginPath();
    ctx.moveTo(x - size/3, y + size/6);
    ctx.lineTo(x, y - size/2);
    ctx.lineTo(x + size/3, y + size/6);
    ctx.closePath();
    ctx.fill();
}

