// Falling leaves
const leaves = [];
for (let i = 0; i < 50; i++) {
    leaves.push({
        x: Math.random() * W,
        y: Math.random() * H,
        size: Math.random() * 8 + 4,
        speed: Math.random() * 2 + 1,
        sway: Math.random() * 0.02,
        swayOffset: Math.random() * Math.PI * 2
    });
}

function drawLeaves() {
    leaves.forEach(leaf => {
        leaf.y += leaf.speed;
        leaf.x += Math.sin(leaf.y * leaf.sway + leaf.swayOffset) * 0.5;

        if (leaf.y > H) {
            leaf.y = -10;
            leaf.x = Math.random() * W;
        }

        ctx.fillStyle = `hsl(${Math.random() * 30 + 20}, 100%, 50%)`;
        ctx.beginPath();
        ctx.ellipse(leaf.x, leaf.y, leaf.size, leaf.size * 0.7, 0, 0, Math.PI * 2);
        ctx.fill();
    });
}

