ctx.fillStyle = '#000000';
for (let i = 0; i < 5; i++) {
    const angle = (i * 2 * Math.PI / 5) - Math.PI/2;
    const x = 200 + Math.cos(angle) * 15;
    const y = 200 + Math.sin(angle) * 15;

    ctx.beginPath();
    ctx.moveTo(x, y);
    for (let j = 0; j < 5; j++) {
        const innerAngle = angle + j * 2 * Math.PI / 5;
        const innerX = x + Math.cos(innerAngle) * 8;
        const innerY = y + Math.sin(innerAngle) * 8;
        ctx.lineTo(innerX, innerY);
    }
    ctx.closePath();
    ctx.fill();
}

