const C6 = '#FFFFFF'; // white

function drawCandle() {
    // Background
    ctx.fillStyle = C1;
    ctx.fillRect(0, 0, W, H);

    // Candle base
    ctx.fillStyle = C2;
    ctx.fillRect(150, 300, 100, 20);

    // Candle body
    ctx.fillStyle = C3;
    ctx.fillRect(170, 200, 60, 100);

    // Wick
    ctx.fillStyle = C6;
    ctx.fillRect(200, 200, 4, 10);

    // Flame flicker - random flickering effect
    const flicker = Math.random();
    if (flicker > 0.3) {
        ctx.fillStyle = C4;
        ctx.fillRect(190, 180, 20, 20);
    }

    if (flicker > 0.6) {
        ctx.fillStyle = C5;
        ctx.fillRect(195, 170, 10, 10);
    }

    if (flicker > 0.9) {
        ctx.fillStyle = C6;
        ctx.fillRect(198, 160, 4, 4);
    }
}

drawCandle();
setInterval(drawCandle, 100);

