// Flame flicker effect - randomly draw flame variations
function drawFlame() {
    // Clear previous flame
    ctx.fillStyle = C_BG;
    ctx.fillRect(190, 190, 20, 40);

    // Draw new flame with random flicker
    const flameType = Math.floor(Math.random() * 3);
    switch(flameType) {
        case 0:
            ctx.fillStyle = C_FLAME1;
            ctx.fillRect(195, 190, 10, 20);
            break;
        case 1:
            ctx.fillStyle = C_FLAME2;
            ctx.fillRect(190, 195, 20, 15);
            break;
        case 2:
            ctx.fillStyle = C_FLAME3;
            ctx.fillRect(192, 192, 16, 18);
            break;
    }
}

// Draw flame initially
drawFlame();

// Set up flickering effect
let flicker = 0;
setInterval(() => {
    flicker++;
    if (flicker % 3 === 0) {
        drawFlame();
    }
}, 100);

