    const x = Math.random() * W;
    const y = Math.random() * 200;
    ctx.fillRect(x, y, 2, 2);
}

// Draw rocket
const rocketX = 190;
const rocketY = 300;

// Rocket body
ctx.fillStyle = ROCKET_BODY;
ctx.fillRect(rocketX, rocketY, 20, 40);

// Rocket details
ctx.fillStyle = ROCKET_DETAIL;
ctx.fillRect(rocketX + 5, rocketY + 5, 10, 10);
ctx.fillRect(rocketX + 5, rocketY + 25, 10, 10);

// Rocket fins
ctx.fillRect(rocketX - 5, rocketY + 20, 5, 15);
ctx.fillRect(rocketX + 20, rocketY + 20, 5, 15);

// Flame effect
ctx.fillStyle = FLAME;
ctx.fillRect(rocketX + 5, rocketY + 40, 10, 10);
ctx.fillRect(rocketX, rocketY + 50, 20, 10);
ctx.fillRect(rocketX + 10, rocketY + 60, 10, 10);

// Animate rocket movement
for (let i = 0; i < 50; i++) {
    setTimeout(() => {
        // Clear canvas
        ctx.fillStyle = SKY;
        ctx.fillRect(0, 0, W, H);

        // Redraw stars
        ctx.fillStyle = STAR;
        for (let j = 0; j < 50; j++) {
            const x = Math.random() * W;
            const y = Math.random() * 200;
            ctx.fillRect(x, y, 2, 2);
        }

        // Redraw ground
        ctx.fillStyle = GROUND;
        ctx.fillRect(0, 300, W, 100);

        // Redraw rocket with new position
        const newY = rocketY - i * 4;
        ctx.fillStyle = ROCKET_BODY;
        ctx.fillRect(rocketX, newY, 20, 40);

        ctx.fillStyle = ROCKET_DETAIL;
        ctx.fillRect(rocketX + 5, newY + 5, 10, 10);
        ctx.fillRect(rocketX + 5, newY + 25, 10, 10);

        ctx.fillRect(rocketX - 5, newY + 20, 5, 15);
        ctx.fillRect(rocketX + 20, newY + 20, 5, 15);

        // Flame effect
        ctx.fillStyle = FLAME;
        ctx.fillRect(rocketX + 5, newY + 40, 10, 10);
        ctx.fillRect(rocketX, newY + 50, 20, 10);
        ctx.fillRect(rocketX + 10, newY + 60, 10, 10);
    }, i * 50);
}

