    ctx.fillRect(225, 225, 20, 5);
    ctx.fillRect(225, 230, 5, 15);
    ctx.fillRect(240, 230, 5, 15);

    // Compass
    ctx.fillStyle = TEXT_COLOR;
    ctx.fillRect(100, 300, 10, 10);
    ctx.fillRect(110, 300, 10, 10);
    ctx.fillRect(105, 305, 10, 10);
    ctx.fillRect(105, 310, 10, 10);

    // Map legend
    ctx.fillStyle = TEXT_COLOR;
    ctx.font = '10px monospace';
    ctx.fillText('TREASURE', 300, 350);
    ctx.fillText('TREE', 300, 370);
    ctx.fillText('ISLAND', 300, 390);

    // Legend symbols
    ctx.fillStyle = TREASURE_COLOR;
    ctx.fillRect(350, 340, 10, 10);
    ctx.fillStyle = TREE_COLOR;
    ctx.fillRect(350, 360, 10, 10);
    ctx.fillStyle = PARCHMENT_HIGHLIGHT;
    ctx.fillRect(350, 380, 10, 10);

} catch(e) {
    console.error(e);
}

