// Draw stack of vinyl records
function drawVinylRecord(x, y, size, color) {
    // Outer circle (vinyl)
    ctx.fillStyle = color;
    ctx.fillRect(x, y, size, size);

    // Inner hole
    ctx.fillStyle = BLACK;
    ctx.fillRect(x + size/2 - size/8, y + size/2 - size/8, size/4, size/4);

    // Grooves (simplified as concentric circles)
    ctx.strokeStyle = WHITE;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.arc(x + size/2, y + size/2, size/3, 0, Math.PI * 2);
    ctx.stroke();

    ctx.beginPath();
    ctx.arc(x + size/2, y + size/2, size/2.5, 0, Math.PI * 2);
    ctx.stroke();
}

