// Define 6 colors for the kaleidoscope pattern
const C1 = '#FF6B6B'; // Red
const C2 = '#4ECDC4'; // Teal
const C3 = '#FFE66D'; // Yellow
const C4 = '#1A535C'; // Dark Teal
const C5 = '#FF9F1C'; // Orange
const C6 = '#2EC4B6'; // Light Teal

// Fill background with dark teal
ctx.fillStyle = C4;
ctx.fillRect(0, 0, W, H);

// Draw central kaleidoscope pattern
const centerX = 200;
const centerY = 200;
const radius = 180;

// Draw 6 large triangles radiating from center
for (let i = 0; i < 6; i++) {
    const angle = (i * Math.PI / 3);
    const x1 = centerX + Math.cos(angle) * radius;
    const y1 = centerY + Math.sin(angle) * radius;
    const x2 = centerX + Math.cos(angle + Math.PI/3) * radius;
    const y2 = centerY + Math.sin(angle + Math.PI/3) * radius;

    ctx.fillStyle = i % 2 === 0 ? C1 : C2;
    ctx.fillRect(x1, y1, 20, 20);
}

// Draw concentric circles with different colors
for (let i = 0; i < 5; i++) {
    const size = 30 + i * 30;
    const x = centerX - size/2;
    const y = centerY - size/2;

    ctx.fillStyle = i % 3 === 0 ? C5 : (i % 3 === 1 ? C6 : C3);
    ctx.fillRect(x, y, size, size);
}

// Draw smaller pattern in center
ctx.fillStyle = C1;
ctx.fillRect(190, 190, 20, 20);

ctx.fillStyle = C2;
ctx.fillRect(180, 180, 20, 20);

ctx.fillStyle = C3;
ctx.fillRect(200, 200, 20, 20);

// Add some scattered rectangles for more kaleidoscope effect
const patterns = [
    [50, 50, 30, 30],
    [320, 50, 30, 30],
    [50, 320, 30, 30],
    [320, 320, 30, 30],
    [100, 100, 20, 20],
    [280, 100, 20, 20],
    [100, 280, 20, 20],
    [280, 280, 20, 20]
];

patterns.forEach(([x, y, w, h]) => {
    ctx.fillStyle = Math.random() > 0.5 ? C5 : C6;
    ctx.fillRect(x, y, w, h);
});

