// Draw circles from outer to inner
for (let radius = maxRadius; radius > 0; radius -= 30) {
    const currentRadius = radius;
    const colorIndex = Math.floor((maxRadius - radius) / 30) % 6;

    switch (colorIndex) {
        case 0: ctx.fillStyle = C1; break;
        case 1: ctx.fillStyle = C2; break;
        case 2: ctx.fillStyle = C3; break;
        case 3: ctx.fillStyle = C4; break;
        case 4: ctx.fillStyle = C5; break;
        case 5: ctx.fillStyle = C6; break;
    }

    // Draw circle using rectangles (chunky 10x10 pixels)
    const circleSize = currentRadius * 2;
    const x = centerX - currentRadius;
    const y = centerY - currentRadius;

    // Draw as a series of rectangles to maintain 10x10 grid
    ctx.fillRect(x, y, circleSize, circleSize);
}

