// Draw flickering flame
function drawFlame() {
    const time = Date.now() / 100;
    const flicker = Math.sin(time) * 5 + Math.sin(time * 0.7) * 3;

    // Main flame body
    ctx.beginPath();
    ctx.moveTo(200, 200);
    ctx.lineTo(200 - 10 - flicker, 180 - flicker);
    ctx.lineTo(200 + 10 + flicker, 180 - flicker);
    ctx.closePath();
    ctx.fillStyle = FLAME;
    ctx.fill();

    // Inner flame glow
    ctx.beginPath();
    ctx.moveTo(200, 195);
    ctx.lineTo(200 - 5 - flicker/2, 185 - flicker/2);
    ctx.lineTo(200 + 5 + flicker/2, 185 - flicker/2);
    ctx.closePath();
    ctx.fillStyle = '#ffff00';
    ctx.fill();

    // Outer flame glow
    ctx.beginPath();
    ctx.moveTo(200, 200);
    ctx.lineTo(200 - 15 - flicker, 175 - flicker);
    ctx.lineTo(200 + 15 + flicker, 175 - flicker);
    ctx.closePath();
    ctx.fillStyle = '#ff6600';
    ctx.fill();
}

