// Draw lightning bolts
function drawLightning(x, y, length, width, color) {
    ctx.strokeStyle = color;
    ctx.lineWidth = width;
    ctx.beginPath();
    ctx.moveTo(x, y);

    let currentX = x;
    let currentY = y;

    for (let i = 0; i < 5; i++) {
        const offsetX = (Math.random() - 0.5) * 30;
        const offsetY = (Math.random() - 0.5) * 20;
        currentX += offsetX;
        currentY += 30;
        ctx.lineTo(currentX, currentY);
    }

    ctx.stroke();
}

