    // Arm shape with slight curve
    ctx.bezierCurveTo(
        startX + Math.cos(angle) * 30,
        startY + Math.sin(angle) * 30,
        startX + Math.cos(angle) * 50,
        startY + Math.sin(angle) * 50,
        startX + Math.cos(angle) * 70,
        startY + Math.sin(angle) * 70
    );
    ctx.lineTo(startX + Math.cos(angle) * 70, startY + Math.sin(angle) * 70);
    ctx.closePath();
    ctx.fill();
}

