const recordColors = ['#8b0000', '#556b2f', '#4b0082', '#2f4f4f', '#8b4513'];
const recordShadows = ['#5a0000', '#2e551a', '#2a004d', '#1a3a3a', '#5d2a00'];

// Draw records from bottom to top
for (let i = 0; i < 5; i++) {
    const y = 250 - i * 20;
    const radius = 120 - i * 10;

    // Record shadow
    ctx.fillStyle = recordShadows[i];
    ctx.beginPath();
    ctx.arc(200, y + 15, radius, 0, Math.PI * 2);
    ctx.fill();

    // Record body
    ctx.fillStyle = recordColors[i];
    ctx.beginPath();
    ctx.arc(200, y, radius, 0, Math.PI * 2);
    ctx.fill();

    // Record center hole
    ctx.fillStyle = '#1a1a1a';
    ctx.beginPath();
    ctx.arc(200, y, 15, 0, Math.PI * 2);
    ctx.fill();

    // Record grooves
    ctx.strokeStyle = '#333';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.arc(200, y, radius - 10, 0, Math.PI * 2);
    ctx.stroke();

    // Groove lines
    for (let j = 0; j < 12; j++) {
        const angle = (j / 12) * Math.PI * 2;
        const x1 = 200 + Math.cos(angle) * (radius - 10);
        const y1 = y + Math.sin(angle) * (radius - 10);
        const x2 = 200 + Math.cos(angle) * (radius - 20);
        const y2 = y + Math.sin(angle) * (radius - 20);
        ctx.beginPath();
        ctx.moveTo(x1, y1);
        ctx.lineTo(x2, y2);
        ctx.stroke();
    }
}

