// Create colorful triangles in a mosaic pattern
const triangleSize = 40;
const offsetX = 20;
const offsetY = 20;

// Palette of 8 colors
const colors = [
  '#FF6B6B', '#4ECDC4', '#45B7D1', '#96CEB4',
  '#FFEAA7', '#DDA0DD', '#98D8C8', '#F7DC6F'
];

// Draw triangles in a grid pattern
for (let y = 0; y < H; y += triangleSize) {
  for (let x = 0; x < W; x += triangleSize) {
    // Alternate between different triangle orientations
    const orientation = Math.floor((x + y) / triangleSize) % 2;

    ctx.beginPath();

    if (orientation === 0) {
      // Upward pointing triangle
      ctx.moveTo(x + offsetX, y + offsetY);
      ctx.lineTo(x + offsetX + triangleSize, y + offsetY);
      ctx.lineTo(x + offsetX + triangleSize/2, y + offsetY + triangleSize);
    } else {
      // Downward pointing triangle
      ctx.moveTo(x + offsetX, y + offsetY + triangleSize);
      ctx.lineTo(x + offsetX + triangleSize, y + offsetY + triangleSize);
      ctx.lineTo(x + offsetX + triangleSize/2, y + offsetY);
    }

    ctx.closePath();

    // Fill with random color from palette
    const colorIndex = Math.floor(Math.random() * colors.length);
    ctx.fillStyle = colors[colorIndex];
    ctx.fill();

    // Add subtle stroke for definition
    ctx.strokeStyle = '#000000';
    ctx.lineWidth = 1;
    ctx.stroke();
  }
}

