      ctx.lineTo(x + size, y);
      ctx.lineTo(x + size/2, y + size);
      ctx.fill();
    } else {
      // Downward triangle
      ctx.beginPath();
      ctx.moveTo(x, y + size);
      ctx.lineTo(x + size, y + size);
      ctx.lineTo(x + size/2, y);
      ctx.fill();
    }

    // Add subtle border for definition
    ctx.strokeStyle = '#0d0d1a';
    ctx.lineWidth = 1;
    ctx.stroke();
  }
}

