const fireworks = [
    {x: 100, y: 200, color: '#ff5252', size: 20},   // Red
    {x: 300, y: 150, color: '#4fc3f7', size: 25},   // Blue
    {x: 200, y: 250, color: '#69f0ae', size: 18},   // Green
    {x: 150, y: 100, color: '#ffd54f', size: 22},   // Yellow
    {x: 350, y: 200, color: '#e91e63', size: 20},   // Pink
];

fireworks.forEach(firework => {
    // Burst effect
    ctx.fillStyle = firework.color;
    for (let i = 0; i < 20; i++) {
        const angle = (i / 20) * Math.PI * 2;
        const distance = Math.random() * firework.size;
        const x = firework.x + Math.cos(angle) * distance;
        const y = firework.y + Math.sin(angle) * distance;
        const radius = Math.random() * 2 + 1;
        ctx.beginPath();
        ctx.arc(x, y, radius, 0, Math.PI * 2);
        ctx.fill();
    }

    // Central core
    ctx.fillStyle = '#ffffff';
    ctx.beginPath();
    ctx.arc(firework.x, firework.y, firework.size * 0.3, 0, Math.PI * 2);
    ctx.fill();

    // Glow effect
    const gradient = ctx.createRadialGradient(
        firework.x, firework.y, 0,
        firework.x, firework.y, firework.size * 1.5
    );
    gradient.addColorStop(0, firework.color);
    gradient.addColorStop(1, 'rgba(255, 255, 255, 0)');

    ctx.fillStyle = gradient;
    ctx.beginPath();
    ctx.arc(firework.x, firework.y, firework.size * 1.5, 0, Math.PI * 2);
    ctx.fill();
});

