// Colorful trails
const colors = ['#ff3300', '#ff9900', '#ffff00', '#00ff00', '#0099ff', '#9900ff'];
for (let i = 0; i < 12; i++) {
    const angle = (i / 12) * Math.PI * 2;
    const length = 30;
    const x1 = 200 + Math.cos(angle) * 8;
    const y1 = 150 + Math.sin(angle) * 8;
    const x2 = 200 + Math.cos(angle) * (8 + length);
    const y2 = 150 + Math.sin(angle) * (8 + length);

    ctx.strokeStyle = colors[i % colors.length];
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.stroke();

    // Trail particles
    ctx.fillStyle = colors[i % colors.length];
    for (let j = 1; j < 5; j++) {
        const px = x1 + (x2 - x1) * j / 5;
        const py = y1 + (y2 - y1) * j / 5;
        const size = 1 + Math.random() * 2;
        ctx.fillRect(px, py, size, size);
    }
}

