function drawFirework(x, y, color) {
    ctx.fillStyle = color;
    ctx.fillRect(x, y, 10, 10);
    ctx.fillRect(x-10, y, 10, 10);
    ctx.fillRect(x+10, y, 10, 10);
    ctx.fillRect(x, y-10, 10, 10);
    ctx.fillRect(x, y+10, 10, 10);
    ctx.fillRect(x-10, y-10, 10, 10);
    ctx.fillRect(x+10, y+10, 10, 10);
    ctx.fillRect(x-10, y+10, 10, 10);
    ctx.fillRect(x+10, y-10, 10, 10);
}

