// Firework burst
const burstX = 200, burstY = 150;
const colors = [C3, C4, C5, C6];
const size = 30;

for(let i = 0; i < 8; i++) {
    const angle = (i * Math.PI / 4);
    const x = burstX + Math.cos(angle) * size;
    const y = burstY + Math.sin(angle) * size;
    ctx.fillStyle = colors[i % colors.length];
    ctx.fillRect(x - 5, y - 5, 10, 10);
}

// Main burst center
ctx.fillStyle = C4;
ctx.fillRect(burstX - 10, burstY - 10, 20, 20);

// Secondary burst
const burst2X = 100, burst2Y = 250;
for(let i = 0; i < 6; i++) {
    const angle = (i * Math.PI / 3);
    const x = burst2X + Math.cos(angle) * size;
    const y = burst2Y + Math.sin(angle) * size;
    ctx.fillStyle = colors[(i + 2) % colors.length];
    ctx.fillRect(x - 5, y - 5, 10, 10);
}

ctx.fillStyle = C5;
ctx.fillRect(burst2X - 10, burst2Y - 10, 20, 20);

