    // Sparkles
    ctx.fillStyle = '#ffffff';
    for (let i = 0; i < 5; i++) {
        const sparkleX = flameX + Math.random() * flameWidth;
        const sparkleY = flameY + Math.random() * flameHeight/2;
        const sparkleSize = Math.random() * 2;
        ctx.fillRect(sparkleX, sparkleY, sparkleSize, sparkleSize);
    }
}

