const SKY = '#87CEEB', GROUND = '#8B4513', TRAIN = '#2F4F4F', SMOKE = '#A9A9A9', WINDOWS = '#87CEFA';
const TRAIN_LENGTH = 120;
const TRAIN_HEIGHT = 40;
const WHEEL_RADIUS = 15;

// Draw sky
ctx.fillStyle = SKY;
ctx.fillRect(0, 0, W, H);

// Draw ground
ctx.fillStyle = GROUND;
ctx.fillRect(0, H - 30, W, 30);

// Draw train body
ctx.fillStyle = TRAIN;
ctx.fillRect(100, H - 70, TRAIN_LENGTH, TRAIN_HEIGHT);

// Draw train windows
ctx.fillStyle = WINDOWS;
for (let i = 0; i < 3; i++) {
    ctx.fillRect(120 + i * 30, H - 65, 20, 20);
}

// Draw train wheels
ctx.fillStyle = '#333';
for (let i = 0; i < 3; i++) {
    const x = 110 + i * 40;
    ctx.beginPath();
    ctx.arc(x, H - 30, WHEEL_RADIUS, 0, Math.PI * 2);
    ctx.fill();

    // Wheel spokes
    ctx.strokeStyle = '#666';
    ctx.lineWidth = 2;
    for (let j = 0; j < 8; j++) {
        const angle = (j / 8) * Math.PI * 2;
        const spokeX = x + Math.cos(angle) * WHEEL_RADIUS;
        const spokeY = H - 30 + Math.sin(angle) * WHEEL_RADIUS;
        ctx.beginPath();
        ctx.moveTo(x, H - 30);
        ctx.lineTo(spokeX, spokeY);
        ctx.stroke();
    }
}

// Draw smoke stack
