    ctx.fillStyle = SHADOW;
    ctx.beginPath();
    ctx.arc(x + recordWidth/2, y + recordHeight/2, 15, 0, Math.PI * 2);
    ctx.fill();

    // Draw record label
    ctx.fillStyle = HIGHLIGHT;
    ctx.beginPath();
    ctx.arc(x + recordWidth/2, y + recordHeight/2, 30, 0, Math.PI * 2);
