// Houses
function drawHouse(x, y, width, height) {
  // Roof
  ctx.fillStyle = ROOF_COLOR;
  ctx.beginPath();
  ctx.moveTo(x, y);
  ctx.lineTo(x + width/2, y - height/2);
  ctx.lineTo(x + width, y);
  ctx.closePath();
  ctx.fill();

  // House body
  ctx.fillStyle = HOUSE_COLOR;
  ctx.fillRect(x, y, width, height);

  // Door
  ctx.fillStyle = DOOR_COLOR;
  ctx.fillRect(x + width/2 - 15, y + height/2, 30, height/2);

  // Windows
  ctx.fillStyle = WINDOW_COLOR;
  ctx.fillRect(x + 10, y + 10, 20, 20);
  ctx.fillRect(x + width - 30, y + 10, 20, 20);
}

