// Trees
function drawTree(x, y) {
  // Trunk
  ctx.fillStyle = '#8B4513';
  ctx.fillRect(x, y, 10, 40);

  // Leaves
  ctx.fillStyle = '#228B22';
  ctx.beginPath();
  ctx.arc(x + 5, y - 15, 20, 0, Math.PI * 2);
  ctx.fill();
}

