    const y2 = CENTER_Y + Math.sin(angle) * RADIUS * 0.7;

    ctx.beginPath();
    ctx.moveTo(CENTER_X, CENTER_Y);
    ctx.lineTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.closePath();

    if (i % 2 === 0) {
        ctx.fillStyle = ACCENT;
