      ctx.lineTo(x + TRIANGLE_SIZE, y);
      ctx.lineTo(x + TRIANGLE_SIZE / 2, y + TRIANGLE_SIZE);
      ctx.fill();

      // Add highlight
      ctx.fillStyle = HIGHLIGHT;
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.lineTo(x + TRIANGLE_SIZE / 2, y);
      ctx.lineTo(x + TRIANGLE_SIZE / 2, y + TRIANGLE_SIZE / 2);
      ctx.fill();
    } else {
      // Downward triangle
      ctx.fillStyle = SHADOW;
      ctx.beginPath();
      ctx.moveTo(x, y + TRIANGLE_SIZE);
      ctx.lineTo(x + TRIANGLE_SIZE, y + TRIANGLE_SIZE);
      ctx.lineTo(x + TRIANGLE_SIZE / 2, y);
      ctx.fill();

      // Add highlight
      ctx.fillStyle = HIGHLIGHT;
      ctx.beginPath();
      ctx.moveTo(x + TRIANGLE_SIZE / 2, y);
      ctx.lineTo(x + TRIANGLE_SIZE, y + TRIANGLE_SIZE / 2);
      ctx.lineTo(x + TRIANGLE_SIZE / 2, y + TRIANGLE_SIZE / 2);
      ctx.fill();
    }
  }
}

