      ctx.moveTo(x, y + TRIANGLE_SIZE);
      ctx.lineTo(x + TRIANGLE_SIZE, y + TRIANGLE_SIZE);
      ctx.lineTo(x + TRIANGLE_SIZE / 2, y);
