    ctx.closePath();

    // Random color from palette
    const colors = [ACCENT, HIGHLIGHT, '#32CD32', '#9370DB', '#FF4500'];
    ctx.fillStyle = colors[Math.floor(Math.random() * colors.length)];
    ctx.fill();
