function drawTornado() {
  const centerX = W / 2;
  const centerY = H / 2;
  const maxRadius = 150;
  const turns = 5;
  const segments = 100;

  ctx.beginPath();
  for (let i = 0; i <= segments; i++) {
    const angle = (i / segments) * turns * Math.PI * 2;
    const radius = maxRadius * (1 - i / segments);
    const x = centerX + Math.cos(angle) * radius;
    const y = centerY + Math.sin(angle) * radius;

    if (i === 0) {
      ctx.moveTo(x, y);
    } else {
      ctx.lineTo(x, y);
    }
  }
  ctx.closePath();
  ctx.fillStyle = ACCENT;
  ctx.fill();

  // Add some texture
  ctx.strokeStyle = HIGHLIGHT;
  ctx.lineWidth = 2;
  ctx.stroke();

  // Draw a central core
  ctx.beginPath();
  ctx.arc(centerX, centerY, 15, 0, Math.PI * 2);
  ctx.fillStyle = SHADOW;
  ctx.fill();
}

drawTornado();

