const SKY = '#0c1445', GROUND = '#1a2a6c', ACCENT = '#ff6b6b', SHADOW = '#ff8e53', HIGHLIGHT = '#ffd166';
const fireworks = [];

// Create fireworks
for (let i = 0; i < 8; i++) {
    fireworks.push({
        x: Math.random() * W,
        y: Math.random() * H * 0.6,
        color: [ACCENT, SHADOW, HIGHLIGHT][Math.floor(Math.random() * 3)],
        size: Math.random() * 3 + 1,
        speed: Math.random() * 2 + 1,
        angle: Math.random() * Math.PI * 2
    });
}

// Draw night sky
ctx.fillStyle = SKY;
ctx.fillRect(0, 0, W, H);

// Draw ground
ctx.fillStyle = GROUND;
ctx.fillRect(0, H - 40, W, 40);

// Draw fireworks
fireworks.forEach((firework, index) => {
    ctx.fillStyle = firework.color;
    ctx.beginPath();
    ctx.arc(firework.x, firework.y, firework.size, 0, Math.PI * 2);
    ctx.fill();

    // Add glow effect
    ctx.fillStyle = firework.color.replace('ff6b6b', 'ff6b6b').replace('ff8e53', 'ff8e53').replace('ffd166', 'ffd166');
    ctx.beginPath();
    ctx.arc(firework.x, firework.y, firework.size + 2, 0, Math.PI * 2);
    ctx.fill();

    // Update position
    firework.x += Math.cos(firework.angle) * firework.speed;
    firework.y += Math.sin(firework.angle) * firework.speed;

    // Reset if out of bounds
    if (firework.x < 0 || firework.x > W || firework.y < 0 || firework.y > H) {
        firework.x = Math.random() * W;
        firework.y = H;
    }
});

