// Draw vinyl records (stacked)
const recordColors = ['#3d405b', '#2d3436', '#636e72', '#1e272e'];
const centerX = W / 2;
const baseRadius = 120;
const gap = 8;

for (let i = 0; i < 5; i++) {
    const radius = baseRadius - i * gap;
    const y = H / 2 + i * 10;

    // Outer ring
    ctx.fillStyle = recordColors[i % recordColors.length];
    ctx.beginPath();
    ctx.arc(centerX, y, radius, 0, Math.PI * 2);
    ctx.fill();

    // Inner hole
    ctx.fillStyle = '#f4f1de';
    ctx.beginPath();
    ctx.arc(centerX, y, radius * 0.2, 0, Math.PI * 2);
    ctx.fill();

    // Groove lines
    ctx.strokeStyle = '#2d3436';
    ctx.lineWidth = 0.5;
    ctx.beginPath();
    for (let j = 0; j < 12; j++) {
        const angle = (j / 12) * Math.PI * 2;
        const startRadius = radius * 0.3;
        const endRadius = radius * 0.9;
        const startX = centerX + Math.cos(angle) * startRadius;
        const startY = y + Math.sin(angle) * startRadius;
        const endX = centerX + Math.cos(angle) * endRadius;
        const endY = y + Math.sin(angle) * endRadius;
        ctx.moveTo(startX, startY);
        ctx.lineTo(endX, endY);
    }
    ctx.stroke();
}

