// Caps with glow effect
function drawGlowingCap(x, y, size, color) {
    // Glow
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.arc(x, y, size + 3, 0, Math.PI * 2);
    ctx.fill();

    // Cap
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.arc(x, y, size, 0, Math.PI * 2);
    ctx.fill();
}

