const drawCentaur = () => {
  // Background
  ctx.fillStyle = '#f0f8ff';
  ctx.fillRect(0, 0, W, H);

  // Horse body
  ctx.fillStyle = '#8b4513';
  ctx.fillRect(120, 180, 160, 100);

  // Horse head
  ctx.fillRect(280, 160, 60, 60);

  // Horse legs
  ctx.fillRect(130, 280, 10, 40);
  ctx.fillRect(170, 280, 10, 40);
  ctx.fillRect(250, 280, 10, 40);
  ctx.fillRect(290, 280, 10, 40);

  // Human torso
  ctx.fillStyle = '#f5deb3';
  ctx.fillRect(160, 120, 80, 60);

  // Human head
  ctx.fillStyle = '#f5deb3';
  ctx.fillRect(180, 80, 40, 40);

  // Human arms
  ctx.fillRect(140, 130, 20, 30);
  ctx.fillRect(260, 130, 20, 30);

  // Bow
  ctx.strokeStyle = '#8b4513';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.moveTo(280, 140);
  ctx.lineTo(240, 120);
  ctx.lineTo(260, 100);
  ctx.stroke();

  // Bow string
  ctx.strokeStyle = '#ffffff';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.moveTo(280, 140);
  ctx.lineTo(240, 120);
  ctx.stroke();

  // Arrow
  ctx.fillStyle = '#696969';
  ctx.fillRect(220, 110, 30, 4);

  // Arrowhead
  ctx.fillStyle = '#333333';
  ctx.beginPath();
  ctx.moveTo(250, 110);
  ctx.lineTo(260, 112);
  ctx.lineTo(250, 114);
  ctx.closePath();
  ctx.fill();
};

