const center = W / 2;
const baseY = 280;

for (let i = 0; i < 5; i++) {
    const y = baseY - i * 20;
    const radius = 80 - i * 5;

    // Outer ring
    ctx.fillStyle = '#1d3557';
    ctx.beginPath();
    ctx.arc(center, y, radius + 5, 0, Math.PI * 2);
    ctx.fill();

    // Vinyl record
    ctx.fillStyle = recordColors[i];
    ctx.beginPath();
    ctx.arc(center, y, radius, 0, Math.PI * 2);
    ctx.fill();

    // Inner hole
    ctx.fillStyle = '#0d0d0d';
    ctx.beginPath();
    ctx.arc(center, y, radius * 0.3, 0, Math.PI * 2);
    ctx.fill();

    // Groove lines
    ctx.strokeStyle = '#333';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.arc(center, y, radius * 0.9, 0, Math.PI * 2);
    ctx.stroke();

    // Shading for depth
    const gradient = ctx.createRadialGradient(
        center - radius * 0.3, y - radius * 0.3, 0,
        center, y, radius
    );
    gradient.addColorStop(0, 'rgba(255, 255, 255, 0.2)');
    gradient.addColorStop(1, 'rgba(0, 0, 0, 0.3)');
    ctx.fillStyle = gradient;
    ctx.beginPath();
    ctx.arc(center, y, radius, 0, Math.PI * 2);
    ctx.fill();
}

