const drawMushroom = (x, y, size, capColor, stemColor) => {
    // Stem
    ctx.fillStyle = stemColor;
    ctx.fillRect(x - size/6, y, size/3, size/2);

    // Cap
    ctx.fillStyle = capColor;
    ctx.beginPath();
    ctx.arc(x, y, size/2, 0, Math.PI, false);
    ctx.fill();

    // Glow effect
    ctx.fillStyle = '#ffffff';
    ctx.globalAlpha = 0.3;
    ctx.beginPath();
    ctx.arc(x, y, size/2 + 2, 0, Math.PI, false);
    ctx.fill();
    ctx.globalAlpha = 1.0;
};

