        // Randomly choose triangle orientation
        const isUpper = Math.random() > 0.5;
        const color = colors[Math.floor(Math.random() * colors.length)];

        ctx.fillStyle = color;

        if (isUpper) {
            // Upper triangle
            ctx.beginPath();
            ctx.moveTo(x, y);
            ctx.lineTo(x + size, y);
            ctx.lineTo(x, y + size);
            ctx.fill();
        } else {
            // Lower triangle
            ctx.beginPath();
            ctx.moveTo(x + size, y + size);
            ctx.lineTo(x + size, y);
            ctx.lineTo(x, y + size);
            ctx.fill();
        }
    }
}

