ctx.beginPath();
for (let i = 0; i < 5; i++) {
    ctx.beginPath();
    for (let j = 0; j < 10; j++) {
        const angle = j * 0.5 + i * 1.2;
        const radius = 50 + i * 8 + Math.sin(j * 0.3) * 5;
        const x = 200 + Math.cos(angle) * radius;
        const y = 200 + Math.sin(angle) * radius;
        if (j === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
    }
    ctx.stroke();
}

