    // Record center hole
    ctx.fillStyle = '#1a1a2e';
    ctx.beginPath();
    ctx.arc(x, y, radius * 0.15, 0, Math.PI * 2);
    ctx.fill();

    // Groove lines
    ctx.strokeStyle = '#2a2a3e';
    ctx.lineWidth = 1;
    for (let j = 0; j < 8; j++) {
        const grooveRadius = radius * (0.2 + j * 0.1);
        ctx.beginPath();
        ctx.arc(x, y, grooveRadius, 0, Math.PI * 2);
        ctx.stroke();
    }
}

