    const angle = (i / 8) * Math.PI * 2;
    const x1 = 320 + Math.cos(angle) * 50;
    const y1 = 80 + Math.sin(angle) * 50;
    const x2 = 320 + Math.cos(angle) * 70;
    const y2 = 80 + Math.sin(angle) * 70;

    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.lineTo(x2 + Math.cos(angle + 0.3) * 20, y2 + Math.sin(angle + 0.3) * 20);
    ctx.closePath();
    ctx.fill();
}

