const cols = Math.ceil(W / triangleSize);

// Define a palette of 8 colors
const colors = [
  '#FF6B6B', '#4ECDC4', '#45B7D1', '#96CEB4',
  '#FFEAA7', '#DDA0DD', '#98D8C8', '#F7DC6F'
];

for (let row = 0; row < rows; row++) {
  for (let col = 0; col < cols; col++) {
    // Alternate triangle orientation for mosaic effect
    const isEvenRow = row % 2 === 0;
    const isEvenCol = col % 2 === 0;

    // Determine triangle orientation
    const isUp = (isEvenRow && isEvenCol) || (!isEvenRow && !isEvenCol);

    ctx.beginPath();

    if (isUp) {
      // Upward triangle
      ctx.moveTo(col * triangleSize, row * triangleSize);
      ctx.lineTo((col + 1) * triangleSize, row * triangleSize);
      ctx.lineTo(col * triangleSize + triangleSize/2, (row + 1) * triangleSize);
    } else {
      // Downward triangle
      ctx.moveTo(col * triangleSize, (row + 1) * triangleSize);
      ctx.lineTo((col + 1) * triangleSize, (row + 1) * triangleSize);
      ctx.lineTo(col * triangleSize + triangleSize/2, row * triangleSize);
    }

    ctx.closePath();

    // Fill with random color from palette
    const color = colors[Math.floor(Math.random() * colors.length)];
    ctx.fillStyle = color;
    ctx.fill();

    // Add subtle border for better separation
    ctx.strokeStyle = '#0d0d1a';
    ctx.lineWidth = 1;
    ctx.stroke();
  }
}

