    const angle = (i / maxRadius) * Math.PI * 2 * turns;
    const radius = i;
    const x = centerX + Math.cos(angle) * radius;
    const y = centerY + Math.sin(angle) * radius;

    // Create spiral with varying darkness
    const darkness = 100 + Math.floor(155 * (1 - i/maxRadius));
    const color = `rgb(${darkness}, ${darkness * 0.8}, ${darkness * 0.6})`;

