// Animate leaves
function animate() {
  ctx.clearRect(0, 0, W, H);

  // Draw background
  ctx.fillStyle = '#87CEEB';
  ctx.fillRect(0, 0, W, H);

  // Draw ground
  ctx.fillStyle = '#8B4513';
  ctx.fillRect(0, 300, W, 100);

  // Draw trees
  ctx.fillStyle = '#228B22';
  ctx.fillRect(50, 250, 30, 150);
  ctx.fillRect(320, 260, 25, 140);
  ctx.fillRect(180, 240, 40, 160);

  // Update and draw leaves
  leaves.forEach(leaf => {
    leaf.y += leaf.speed;
    leaf.x += leaf.wind;

    // Reset leaf if it goes off screen
    if (leaf.y > H) {
      leaf.y = -10;
      leaf.x = Math.random() * W;
    }

    ctx.fillStyle = leaf.color;
    ctx.beginPath();
    ctx.ellipse(leaf.x, leaf.y, leaf.size, leaf.size/2, 0, 0, Math.PI * 2);
    ctx.fill();
  });

  requestAnimationFrame(animate);
}

