    color: '#0000ff',
    glow: '#6666ff'
};

// Function to draw a lightsaber
function drawSaber(saber) {
    // Draw glow effect
    ctx.strokeStyle = saber.glow;
    ctx.lineWidth = 8;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(saber.x, saber.y);
    ctx.lineTo(
        saber.x + Math.cos(saber.angle) * saber.length,
        saber.y + Math.sin(saber.angle) * saber.length
    );
    ctx.stroke();

    // Draw main blade
    ctx.strokeStyle = saber.color;
    ctx.lineWidth = 4;
    ctx.beginPath();
    ctx.moveTo(saber.x, saber.y);
    ctx.lineTo(
        saber.x + Math.cos(saber.angle) * saber.length,
        saber.y + Math.sin(saber.angle) * saber.length
    );
    ctx.stroke();

    // Draw hilt
    ctx.fillStyle = '#333333';
    ctx.fillRect(saber.x - 15, saber.y - 10, 30, 20);
    ctx.fillStyle = '#666666';
    ctx.fillRect(saber.x - 10, saber.y - 5, 20, 10);
}

