// Mushrooms
function drawMushroom(x, y, size, capColor, stemColor) {
    // Stem
    ctx.fillStyle = stemColor;
    ctx.fillRect(x - size/6, y, size/3, size/2);

    // Cap
    ctx.fillStyle = capColor;
    ctx.beginPath();
    ctx.arc(x, y, size/2, 0, Math.PI, false);
    ctx.fill();

    // Glow effect
    ctx.fillStyle = 'rgba(255, 255, 255, 0.2)';
    ctx.beginPath();
    ctx.arc(x, y, size/2 + 2, 0, Math.PI, false);
    ctx.fill();
}

