const cols = Math.ceil(W / triangleSize);

// Triangle colors
const colors = [
  '#e63946', '#f4a261', '#e9c46a', '#2a9d8f',
  '#264653', '#457b9d', '#f72585', '#7209b7'
];

// Draw triangles in a grid pattern
for (let row = 0; row < rows; row++) {
  for (let col = 0; col < cols; col++) {
    const x = col * triangleSize;
    const y = row * triangleSize;

    // Alternate between different triangle orientations
    if ((row + col) % 2 === 0) {
      // Upward pointing triangle
      ctx.fillStyle = colors[Math.floor(Math.random() * colors.length)];
      ctx.beginPath();
      ctx.moveTo(x, y + triangleSize);
      ctx.lineTo(x + triangleSize, y + triangleSize);
      ctx.lineTo(x + triangleSize/2, y);
      ctx.fill();
    } else {
      // Downward pointing triangle
      ctx.fillStyle = colors[Math.floor(Math.random() * colors.length)];
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.lineTo(x + triangleSize, y);
      ctx.lineTo(x + triangleSize/2, y + triangleSize);
      ctx.fill();
    }
  }
}

