    // Create curved tentacles
    for (let j = 0; j < 10; j++) {
        const t = j / 10;
        const offsetX = Math.sin(t * 10 + i) * 10;
        const offsetY = j * 10;
        const x = startX + offsetX;
        const y = startY + offsetY;
        ctx.lineTo(x, y);
    }

    ctx.strokeStyle = tentacleColors[i % tentacleColors.length];
    ctx.lineWidth = 3;
    ctx.stroke();

