    const y = 250 - i * 15;
    const radius = 100 - i * 5;

    // Record base
    ctx.fillStyle = recordColors[i];
    ctx.beginPath();
    ctx.arc(200, y, radius, 0, Math.PI * 2);
    ctx.fill();

    // Record shadow
    ctx.fillStyle = recordShadows[i];
    ctx.beginPath();
    ctx.arc(200, y, radius, 0, Math.PI * 2);
    ctx.fill();

    // Center hole
    ctx.fillStyle = '#1a1a1a';
    ctx.beginPath();
    ctx.arc(200, y, radius * 0.15, 0, Math.PI * 2);
    ctx.fill();

    // Groove lines
    ctx.strokeStyle = '#333';
    ctx.lineWidth = 0.5;
    ctx.beginPath();
    ctx.arc(200, y, radius * 0.85, 0, Math.PI * 2);
    ctx.stroke();

    // Inner grooves
    for (let j = 0; j < 5; j++) {
        const grooveRadius = radius * (0.75 - j * 0.05);
        ctx.beginPath();
        ctx.arc(200, y, grooveRadius, 0, Math.PI * 2);
        ctx.stroke();
    }
}

