const recordColors = ['#8B4513', '#A0522D', '#CD853F', '#D2691E', '#DAA520'];
const centerX = W / 2;
const baseY = 300;

for (let i = 0; i < 5; i++) {
    const y = baseY - i * 15;
    const radius = 80 - i * 5;

    // Record shadow
    ctx.fillStyle = '#2a2a2a';
    ctx.beginPath();
    ctx.arc(centerX, y + 5, radius, 0, Math.PI * 2);
    ctx.fill();

    // Record body
    ctx.fillStyle = recordColors[i];
    ctx.beginPath();
    ctx.arc(centerX, y, radius, 0, Math.PI * 2);
    ctx.fill();

    // Record center
    ctx.fillStyle = '#1a1a1a';
    ctx.beginPath();
    ctx.arc(centerX, y, radius * 0.2, 0, Math.PI * 2);
    ctx.fill();

    // Groove lines
    ctx.strokeStyle = '#333';
    ctx.lineWidth = 1;
    for (let j = 0; j < 12; j++) {
        const angle = (j / 12) * Math.PI * 2;
        const x1 = centerX + Math.cos(angle) * radius * 0.3;
        const y1 = y + Math.sin(angle) * radius * 0.3;
        const x2 = centerX + Math.cos(angle) * radius * 0.9;
        const y2 = y + Math.sin(angle) * radius * 0.9;
        ctx.beginPath();
        ctx.moveTo(x1, y1);
        ctx.lineTo(x2, y2);
        ctx.stroke();
    }
}

