// Draw kaleidoscope pattern with 6-fold symmetry
const centerX = W / 2;
const centerY = H / 2;
const maxRadius = Math.min(W, H) / 2 - 20;

// Create gradient for color transitions
const colors = ['#ff6b6b', '#4ecdc4', '#45b7d1', '#96ceb4', '#feca57', '#ff9ff3'];

for (let i = 0; i < 6; i++) {
    const angle = (i * Math.PI) / 3;

    // Draw radial segments
    ctx.beginPath();
    ctx.moveTo(centerX, centerY);
    ctx.arc(centerX, centerY, maxRadius, angle, angle + Math.PI / 3);
    ctx.closePath();

    // Create gradient for segment
    const gradient = ctx.createRadialGradient(
        centerX, centerY, 0,
        centerX, centerY, maxRadius
    );

    const colorIndex = i % colors.length;
    gradient.addColorStop(0, colors[colorIndex]);
    gradient.addColorStop(1, colors[(colorIndex + 3) % colors.length]);

    ctx.fillStyle = gradient;
    ctx.fill();

    // Draw inner pattern
    ctx.strokeStyle = '#ffffff';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.arc(centerX, centerY, maxRadius * 0.7, angle, angle + Math.PI / 3);
    ctx.stroke();

    // Draw concentric circles
    for (let r = 20; r < maxRadius * 0.7; r += 20) {
        ctx.beginPath();
        ctx.arc(centerX, centerY, r, angle, angle + Math.PI / 3);
        ctx.stroke();
    }
}

