        ctx.beginPath();
        ctx.moveTo(centerX, centerY);
        ctx.arc(centerX, centerY, layerRadius * 0.7, startAngle, endAngle);
        ctx.closePath();

        const highlight = `hsla(${hue + i * 30}, 80%, 80%, 0.3)`;
        ctx.fillStyle = highlight;
        ctx.fill();
    }
}

