// Create colorful triangle mosaic
const triangleSize = 40;
const rows = Math.ceil(H / triangleSize);
const cols = Math.ceil(W / triangleSize);

// Define a palette of 8 colors
const colors = [
  '#ff6b6b', '#4ecdc4', '#45b7d1', '#96ceb4',
  '#feca57', '#ff9ff3', '#54a0ff', '#5f27cd'
];

// Draw triangles in a grid pattern
for (let row = 0; row < rows; row++) {
  for (let col = 0; col < cols; col++) {
    const x = col * triangleSize;
    const y = row * triangleSize;

    // Alternate triangle orientation for visual interest
    const isEvenRow = row % 2 === 0;
    const isEvenCol = col % 2 === 0;

    // Choose color
    const colorIndex = (row + col) % colors.length;
    ctx.fillStyle = colors[colorIndex];

    // Draw triangle
    ctx.beginPath();
    if (isEvenRow && isEvenCol || !isEvenRow && !isEvenCol) {
      // Right triangle
      ctx.moveTo(x, y);
      ctx.lineTo(x + triangleSize, y);
      ctx.lineTo(x, y + triangleSize);
    } else {
      // Left triangle
      ctx.moveTo(x + triangleSize, y);
      ctx.lineTo(x + triangleSize, y + triangleSize);
      ctx.lineTo(x, y + triangleSize);
    }
    ctx.fill();
  }
}

