const jellyfishX = 200;
const jellyfishY = 250;
const bodyRadius = 60;

// Main body with gradient effect
ctx.fillStyle = '#ff6bff';
ctx.beginPath();
ctx.arc(jellyfishX, jellyfishY, bodyRadius, 0, Math.PI * 2);
ctx.fill();

// Add inner highlight
ctx.fillStyle = '#ff9bff';
ctx.beginPath();
ctx.arc(jellyfishX - 15, jellyfishY - 15, bodyRadius * 0.4, 0, Math.PI * 2);
ctx.fill();

// Tentacles
const tentacleCount = 8;
const tentacleLength = 120;
const tentacleWidth = 8;

for (let i = 0; i < tentacleCount; i++) {
    const angle = (i / tentacleCount) * Math.PI * 2;
    const startX = jellyfishX + Math.cos(angle) * bodyRadius;
    const startY = jellyfishY + Math.sin(angle) * bodyRadius;

    // Tentacle base
    ctx.fillStyle = '#ff6bff';
    ctx.beginPath();
    ctx.ellipse(startX, startY, tentacleWidth, 15, angle, 0, Math.PI * 2);
    ctx.fill();

    // Tentacle tip
    ctx.fillStyle = '#ff9bff';
    ctx.beginPath();
    ctx.ellipse(startX, startY + tentacleLength, tentacleWidth * 0.8, 10, angle, 0, Math.PI * 2);
    ctx.fill();

    // Add some gradient to tentacles
    for (let j = 0; j < 5; j++) {
        const y = startY + (tentacleLength * j / 5);
        const width = tentacleWidth * (1 - j/5);
        ctx.fillStyle = `rgba(255, 107, 255, ${0.8 - j/10})`;
        ctx.beginPath();
        ctx.ellipse(startX, y, width, 3, angle, 0, Math.PI * 2);
        ctx.fill();
    }
}

