// Pumpkins
const drawPumpkin = (x, y, size, color) => {
    // Stem
    ctx.fillStyle = '#8b4513';
    ctx.fillRect(x - 5, y - size, 10, size/3);

    // Pumpkin body
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.ellipse(x, y, size, size * 0.7, 0, 0, Math.PI * 2);
    ctx.fill();

    // Shadow
    ctx.fillStyle = '#1a2b1c';
    ctx.beginPath();
    ctx.ellipse(x, y + size * 0.3, size * 0.8, size * 0.3, 0, 0, Math.PI * 2);
    ctx.fill();

    // Face details
    ctx.fillStyle = '#000';
    // Eyes
    ctx.beginPath();
    ctx.arc(x - size/3, y - size/6, size/8, 0, Math.PI * 2);
    ctx.arc(x + size/3, y - size/6, size/8, 0, Math.PI * 2);
    ctx.fill();

    // Nose
    ctx.beginPath();
    ctx.moveTo(x, y + size/6);
    ctx.lineTo(x - size/6, y + size/3);
    ctx.lineTo(x + size/6, y + size/3);
    ctx.closePath();
    ctx.fill();

    // Mouth
    ctx.beginPath();
    ctx.arc(x, y + size/2, size/4, 0, Math.PI);
    ctx.stroke();
};

