    const y = 250 + Math.sin(angle) * 65;
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(x + Math.cos(angle) * 15, y + Math.sin(angle) * 15);
    ctx.strokeStyle = '#006400';
    ctx.lineWidth = 3;
    ctx.stroke();
}

