// Stack of vinyl records
const recordColors = ['#e63946', '#457b9d', '#f4a261', '#2a9d8f', '#e9c46a'];
const centerX = W/2;
const baseY = 300;

// Draw each record in the stack
for (let i = 0; i < 5; i++) {
    const y = baseY - i * 15;
    const radius = 80 - i * 5;

    // Record shadow
    ctx.fillStyle = '#1d3557';
    ctx.beginPath();
    ctx.ellipse(centerX, y + 10, radius - 10, 5, 0, 0, Math.PI * 2);
    ctx.fill();

    // Record body
    ctx.fillStyle = recordColors[i];
    ctx.beginPath();
    ctx.ellipse(centerX, y, radius, radius - 5, 0, 0, Math.PI * 2);
    ctx.fill();

    // Record center
    ctx.fillStyle = '#1d3557';
    ctx.beginPath();
    ctx.ellipse(centerX, y, radius * 0.2, radius * 0.2, 0, 0, Math.PI * 2);
    ctx.fill();

    // Groove lines
    ctx.strokeStyle = '#1d3557';
    ctx.lineWidth = 1;
    for (let j = 0; j < 8; j++) {
        const angle = (j * 45) * Math.PI / 180;
        ctx.beginPath();
        ctx.arc(centerX, y, radius * 0.8, angle, angle + Math.PI);
        ctx.stroke();
    }
}

