// Draw kaleidoscope pattern with 6-fold symmetry
const centerX = W / 2;
const centerY = H / 2;
const maxRadius = Math.min(W, H) / 2;

// Define a palette of vibrant colors
const colors = ['#ff6b6b', '#4ecdc4', '#45b7d1', '#96ceb4', '#feca57', '#ff9ff3'];

// Draw 6 sections of the kaleidoscope
for (let i = 0; i < 6; i++) {
    const angle = (i * Math.PI) / 3;

    // Create a gradient for each section
    const gradient = ctx.createLinearGradient(
        centerX, centerY,
        centerX + Math.cos(angle) * maxRadius,
        centerY + Math.sin(angle) * maxRadius
    );

    gradient.addColorStop(0, colors[i % colors.length]);
    gradient.addColorStop(1, colors[(i + 1) % colors.length]);

    ctx.fillStyle = gradient;

    // Draw a triangle for each section
    ctx.beginPath();
    ctx.moveTo(centerX, centerY);
    ctx.lineTo(
        centerX + Math.cos(angle) * maxRadius,
        centerY + Math.sin(angle) * maxRadius
    );
    ctx.lineTo(
        centerX + Math.cos(angle + Math.PI / 3) * maxRadius,
        centerY + Math.sin(angle + Math.PI / 3) * maxRadius
    );
    ctx.closePath();
    ctx.fill();
}

// Add some circular patterns for more complexity
for (let i = 0; i < 8; i++) {
    const radius = (i + 1) * 20;
    const angle = (i * Math.PI) / 4;

    ctx.strokeStyle = colors[i % colors.length];
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(centerX, centerY, radius, 0, Math.PI * 2);
    ctx.stroke();

    // Add some small circles for detail
    ctx.fillStyle = colors[(i + 3) % colors.length];
    ctx.beginPath();
    ctx.arc(
        centerX + Math.cos(angle) * radius,
        centerY + Math.sin(angle) * radius,
        5, 0, Math.PI * 2
    );
    ctx.fill();
}

