    const color = colors[Math.floor(Math.random() * colors.length)];

    ctx.fillStyle = color;

    const triangleType = Math.floor(Math.random() * 4);

    switch(triangleType) {
        case 0: // Point up
            ctx.beginPath();
            ctx.moveTo(x, y - size/2);
            ctx.lineTo(x - size/2, y + size/2);
            ctx.lineTo(x + size/2, y + size/2);
            ctx.closePath();
            ctx.fill();
            break;
        case 1: // Point down
            ctx.beginPath();
            ctx.moveTo(x, y + size/2);
            ctx.lineTo(x - size/2, y - size/2);
            ctx.lineTo(x + size/2, y - size/2);
            ctx.closePath();
            ctx.fill();
            break;
        case 2: // Point left
            ctx.beginPath();
            ctx.moveTo(x - size/2, y);
            ctx.lineTo(x + size/2, y - size/2);
            ctx.lineTo(x + size/2, y + size/2);
            ctx.closePath();
            ctx.fill();
            break;
        case 3: // Point right
            ctx.beginPath();
            ctx.moveTo(x + size/2, y);
            ctx.lineTo(x - size/2, y - size/2);
            ctx.lineTo(x - size/2, y + size/2);
            ctx.closePath();
            ctx.fill();
            break;
    }
}

