const drawWerewolf = () => {
  // Background - dark night sky
  ctx.fillStyle = '#0a0a2a';
  ctx.fillRect(0, 0, W, H);

  // Stars
  ctx.fillStyle = '#ffffff';
  for (let i = 0; i < 100; i++) {
    const x = Math.random() * W;
    const y = Math.random() * H;
    const size = Math.random() * 2;
    ctx.fillRect(x, y, size, size);
  }

  // Moon
  ctx.fillStyle = '#e0e0ff';
  ctx.beginPath();
  ctx.arc(350, 50, 30, 0, Math.PI * 2);
  ctx.fill();

  // Ground
  ctx.fillStyle = '#2a2a1a';
  ctx.fillRect(0, 300, W, 100);

  // Werewolf body - dark gray
  ctx.fillStyle = '#333333';
  ctx.beginPath();
  ctx.ellipse(200, 320, 80, 40, 0, 0, Math.PI * 2);
  ctx.fill();

  // Werewolf head - darker gray
  ctx.fillStyle = '#222222';
  ctx.beginPath();
  ctx.ellipse(200, 260, 50, 40, 0, 0, Math.PI * 2);
  ctx.fill();

  // Werewolf ears - pointed
  ctx.fillStyle = '#222222';
  ctx.beginPath();
  ctx.moveTo(170, 230);
  ctx.lineTo(160, 200);
  ctx.lineTo(180, 230);
  ctx.fill();

  ctx.beginPath();
  ctx.moveTo(230, 230);
  ctx.lineTo(240, 200);
  ctx.lineTo(220, 230);
  ctx.fill();

  // Werewolf eyes - glowing yellow
  ctx.fillStyle = '#ffff00';
  ctx.beginPath();
  ctx.ellipse(190, 250, 8, 12, 0, 0, Math.PI * 2);
  ctx.fill();

  ctx.beginPath();
  ctx.ellipse(210, 250, 8, 12, 0, 0, Math.PI * 2);
  ctx.fill();

  // Werewolf nose - black
  ctx.fillStyle = '#000000';
  ctx.beginPath();
  ctx.ellipse(200, 265, 10, 8, 0, 0, Math.PI * 2);
  ctx.fill();

  // Werewolf mouth - open, showing fangs
  ctx.fillStyle = '#ff0000';
  ctx.beginPath();
  ctx.moveTo(190, 275);
  ctx.lineTo(200, 290);
  ctx.lineTo(210, 275);
  ctx.fill();

  // Werewolf legs - dark gray
  ctx.fillStyle = '#333333';
  ctx.fillRect(160, 320, 20, 40);
  ctx.fillRect(220, 320, 20, 40);

  // Werewolf tail - dark gray
  ctx.fillStyle = '#333333';
  ctx.beginPath();
  ctx.ellipse(280, 310, 30, 10, Math.PI/4, 0, Math.PI * 2);
  ctx.fill();

  // Werewolf claws - black
  ctx.fillStyle = '#000000';
  ctx.fillRect(155, 355, 8, 10);
  ctx.fillRect(235, 355, 8, 10);

  // Howling pose - mouth open wide
  ctx.strokeStyle = '#ffffff';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(200, 270, 20, 0, Math.PI);
  ctx.stroke();

  // Shadow under werewolf
  ctx.fillStyle = '#1a1a1a';
  ctx.beginPath();
  ctx.ellipse(200, 350, 60, 10, 0, 0, Math.PI * 2);
  ctx.fill();
};

