// Draw leaves
function drawLeaves() {
    leaves.forEach(leaf => {
        ctx.fillStyle = leaf.color;
        ctx.beginPath();
        ctx.ellipse(leaf.x, leaf.y, leaf.size, leaf.size/2, 0, 0, Math.PI * 2);
        ctx.fill();
    });
}

// Animate leaves
function animate() {
    ctx.clearRect(0, 0, W, H);

    // Redraw sky and ground
    ctx.fillStyle = '#87CEEB';
    ctx.fillRect(0, 0, W, H);
    ctx.fillStyle = '#8B4513';
    ctx.fillRect(0, 300, W, 100);
    ctx.fillStyle = '#228B22';
    ctx.fillRect(0, 300, W, 20);

    // Redraw tree
    ctx.fillStyle = '#8B4513';
    ctx.fillRect(190, 220, 20, 80);
    ctx.fillStyle = '#228B22';
    ctx.beginPath();
    ctx.arc(200, 200, 60, 0, Math.PI * 2);
    ctx.fill();

    // Update and draw leaves
    leaves.forEach(leaf => {
        leaf.y += leaf.speed;
        leaf.x += leaf.wind;

        if (leaf.y > H) {
            leaf.y = -10;
            leaf.x = Math.random() * W;
        }

        ctx.fillStyle = leaf.color;
        ctx.beginPath();
        ctx.ellipse(leaf.x, leaf.y, leaf.size, leaf.size/2, 0, 0, Math.PI * 2);
        ctx.fill();
    });

    requestAnimationFrame(animate);
}

