// Draw leaves
leaves.forEach(leaf => {
    ctx.fillStyle = `rgb(${Math.floor(Math.random() * 100 + 150)}, ${Math.floor(Math.random() * 50 + 50)}, 0)`;
    ctx.beginPath();
    ctx.arc(leaf.x, leaf.y, leaf.size, 0, Math.PI * 2);
    ctx.fill();
});

// Simulate falling leaves
function animate() {
    ctx.clearRect(0, 0, W, H);
    ctx.fillStyle = '#87CEEB';
    ctx.fillRect(0, 0, W, H);

    // Redraw ground
    ctx.fillStyle = '#8B4513';
    ctx.fillRect(0, 300, W, 100);
    ctx.fillStyle = '#228B22';
    ctx.fillRect(0, 300, W, 20);

    // Redraw trees
    ctx.fillStyle = '#228B22';
    ctx.fillRect(50, 200, 20, 100);
    ctx.fillRect(150, 180, 20, 120);
    ctx.fillRect(250, 210, 20, 90);
    ctx.fillRect(350, 190, 20, 110);

    // Update and draw leaves
    leaves.forEach(leaf => {
        leaf.y += leaf.speed;
        leaf.x += leaf.sway;
        if (leaf.y > H) leaf.y = 0;
        if (leaf.x > W) leaf.x = 0;
        if (leaf.x < 0) leaf.x = W;

        ctx.fillStyle = `rgb(${Math.floor(Math.random() * 100 + 150)}, ${Math.floor(Math.random() * 50 + 50)}, 0)`;
        ctx.beginPath();
        ctx.arc(leaf.x, leaf.y, leaf.size, 0, Math.PI * 2);
        ctx.fill();
    });

    requestAnimationFrame(animate);
}

