// Flowers
function drawFlower(x, y, color) {
    // Stem
    ctx.fillStyle = '#228B22';
    ctx.fillRect(x - 2, y, 4, 40);

    // Petals
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.arc(x, y - 10, 12, 0, Math.PI * 2);
    ctx.fill();

    // Center
    ctx.fillStyle = '#FFA500';
    ctx.beginPath();
    ctx.arc(x, y - 10, 5, 0, Math.PI * 2);
    ctx.fill();
}

