const recordColors = ['#8b0000', '#5d0000', '#3a0000', '#6b0000', '#4a0000'];
const centerX = W / 2;
const baseY = 300;

for (let i = 0; i < 5; i++) {
    const y = baseY - i * 15;
    const radius = 80 - i * 5;

    // Record outer ring
    ctx.fillStyle = recordColors[i];
    ctx.beginPath();
    ctx.arc(centerX, y, radius, 0, Math.PI * 2);
    ctx.fill();

    // Record inner hole
    ctx.fillStyle = '#1a1a2e';
    ctx.beginPath();
    ctx.arc(centerX, y, radius * 0.2, 0, Math.PI * 2);
    ctx.fill();

    // Record grooves
    ctx.strokeStyle = '#333';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.arc(centerX, y, radius * 0.8, 0, Math.PI * 2);
    ctx.stroke();

    // Groove lines
    for (let j = 0; j < 12; j++) {
        const angle = (j / 12) * Math.PI * 2;
        const startX = centerX + Math.cos(angle) * radius * 0.8;
        const startY = y + Math.sin(angle) * radius * 0.8;
        const endX = centerX + Math.cos(angle) * radius * 0.2;
        const endY = y + Math.sin(angle) * radius * 0.2;

        ctx.beginPath();
        ctx.moveTo(startX, startY);
        ctx.lineTo(endX, endY);
        ctx.stroke();
    }
}

