// Draw pieces
const drawPiece = (color, x, y, type) => {
    ctx.fillStyle = color;
    ctx.beginPath();
    if (type === 'king') {
        ctx.arc(x + squareSize/2, y + squareSize/2, squareSize/3, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = color === '#000000' ? '#FFFFFF' : '#000000';
        ctx.fillRect(x + squareSize/2 - 5, y + squareSize/2 - 10, 10, 20);
    } else if (type === 'queen') {
        ctx.arc(x + squareSize/2, y + squareSize/2, squareSize/3, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = color === '#000000' ? '#FFFFFF' : '#000000';
        ctx.fillRect(x + squareSize/2 - 8, y + squareSize/2 - 15, 16, 10);
    } else if (type === 'rook') {
        ctx.fillRect(x + squareSize/4, y + squareSize/4, squareSize/2, squareSize/2);
        ctx.fillStyle = color === '#000000' ? '#FFFFFF' : '#000000';
        ctx.fillRect(x + squareSize/4 + 2, y + squareSize/4 + 2, squareSize/2 - 4, squareSize/2 - 4);
    } else if (type === 'bishop') {
        ctx.beginPath();
        ctx.arc(x + squareSize/2, y + squareSize/2, squareSize/3, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = color === '#000000' ? '#FFFFFF' : '#000000';
        ctx.fillRect(x + squareSize/2 - 6, y + squareSize/2 - 12, 12, 8);
    } else if (type === 'knight') {
        ctx.beginPath();
        ctx.arc(x + squareSize/2, y + squareSize/2, squareSize/3, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = color === '#000000' ? '#FFFFFF' : '#000000';
        ctx.fillRect(x + squareSize/2 - 4, y + squareSize/2 - 10, 8, 12);
    } else if (type === 'pawn') {
        ctx.beginPath();
        ctx.arc(x + squareSize/2, y + squareSize/2, squareSize/3, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = color === '#000000' ? '#FFFFFF' : '#000000';
        ctx.fillRect(x + squareSize/2 - 4, y + squareSize/2 - 8, 8, 8);
    }
};

