const centerY = 300;
const maxRadius = 150;
const spiralTurns = 8;
const baseRadius = 10;

ctx.fillStyle = '#4a4a4a';
for (let i = 0; i < 200; i++) {
    const angle = (i / 200) * spiralTurns * Math.PI * 2;
    const radius = baseRadius + (i / 200) * (maxRadius - baseRadius);
    const x = centerX + Math.cos(angle) * radius;
    const y = centerY - Math.sin(angle) * radius;

    // Create a spiral effect with varying sizes
    const size = Math.max(2, 10 - (i / 200) * 8);
    ctx.fillRect(x - size/2, y - size/2, size, size);
}

// Add some cloud-like texture to the tornado
ctx.fillStyle = '#666666';
for (let i = 0; i < 30; i++) {
    const angle = Math.random() * Math.PI * 2;
    const radius = Math.random() * 100 + 20;
    const x = centerX + Math.cos(angle) * radius;
    const y = centerY - Math.sin(angle) * radius;
    const size = Math.random() * 15 + 5;
    ctx.fillRect(x - size/2, y - size/2, size, size);
}

