// Tornado spiral
const centerX = 200;
const centerY = 300;
const maxRadius = 100;
const spiralTurns = 5;
const steps = 200;

ctx.strokeStyle = '#333';
ctx.lineWidth = 3;

for (let i = 0; i < steps; i++) {
    const t = i / steps;
    const radius = maxRadius * (1 - t);
    const angle = t * spiralTurns * Math.PI * 2;

    const x1 = centerX + Math.cos(angle) * radius;
    const y1 = centerY - Math.sin(angle) * radius;

    const x2 = centerX + Math.cos(angle + 0.1) * (radius - 5);
    const y2 = centerY - Math.sin(angle + 0.1) * (radius - 5);

    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.stroke();
}

