// Falling leaves
const leaves = [];
for (let i = 0; i < 50; i++) {
    leaves.push({
        x: Math.random() * W,
        y: Math.random() * H,
        size: Math.random() * 8 + 4,
        speed: Math.random() * 2 + 1,
        sway: Math.random() * 2 - 1,
        swaySpeed: Math.random() * 0.02 + 0.01
    });
}

// Draw leaves
function drawLeaves() {
    leaves.forEach(leaf => {
        leaf.y += leaf.speed;
        leaf.x += Math.sin(leaf.y * leaf.swaySpeed) * leaf.sway;

        if (leaf.y > H) {
            leaf.y = -10;
            leaf.x = Math.random() * W;
        }

        // Leaf color
        const colors = ['#FF4500', '#FF6347', '#FFA500', '#FF8C00', '#D2691E'];
        ctx.fillStyle = colors[Math.floor(Math.random() * colors.length)];

        ctx.beginPath();
        ctx.ellipse(leaf.x, leaf.y, leaf.size, leaf.size * 0.6, 0, 0, Math.PI * 2);
        ctx.fill();
    });
}

