// Draw saber glow effect
function drawSaberGlow(saber) {
    ctx.strokeStyle = saber.glow;
    ctx.lineWidth = 8;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(saber.x, saber.y);
    const endX = saber.x + Math.cos(saber.angle) * saber.length;
    const endY = saber.y + Math.sin(saber.angle) * saber.length;
    ctx.lineTo(endX, endY);
    ctx.stroke();

    // Add glow at the tip
    ctx.fillStyle = saber.glow;
    ctx.beginPath();
    ctx.arc(endX, endY, 8, 0, Math.PI * 2);
    ctx.fill();
}

// Draw saber hilt and blade
function drawSaber(saber) {
    // Draw hilt
    ctx.fillStyle = '#333333';
    ctx.fillRect(saber.x - 15, saber.y - 15, 30, 30);

    // Draw blade
    ctx.fillStyle = saber.color;
    ctx.fillRect(saber.x, saber.y, 10, saber.length);

    // Add some detail to hilt
    ctx.fillStyle = '#555555';
    ctx.fillRect(saber.x - 10, saber.y - 10, 20, 5);
}

