// Flame flicker - multiple layers for realistic effect
function drawFlame() {
    const colors = ['#ff9900', '#ff6600', '#ff3300', '#ff0000'];
    const size = 15;
    const x = 198;
    const y = 155;

    for (let i = 0; i < 4; i++) {
        const offsetX = Math.random() * 4 - 2;
        const offsetY = Math.random() * 3 - 1;
        const radius = size - i * 2 + Math.random() * 3;
        const alpha = 0.7 - i * 0.15 + Math.random() * 0.2;

        ctx.fillStyle = colors[i];
        ctx.globalAlpha = alpha;
        ctx.beginPath();
        ctx.arc(x + offsetX, y + offsetY, radius, 0, Math.PI * 2);
        ctx.fill();
    }

    ctx.globalAlpha = 1;
}

// Draw flame multiple times for flicker effect
drawFlame();
drawFlame();
drawFlame();

