// Mushrooms
function drawMushroom(x, y, capRadius, stemHeight, capColor, stemColor, glowColor) {
    // Stem
    ctx.fillStyle = stemColor;
    ctx.fillRect(x - 5, y, 10, stemHeight);

    // Cap
    ctx.fillStyle = capColor;
    ctx.beginPath();
    ctx.arc(x, y, capRadius, 0, Math.PI * 2);
    ctx.fill();

    // Glow
    ctx.fillStyle = glowColor;
    ctx.globalAlpha = 0.3;
    ctx.beginPath();
    ctx.arc(x, y, capRadius + 3, 0, Math.PI * 2);
    ctx.fill();
    ctx.globalAlpha = 1.0;
}

