const tentacleLength = 80;
const tentacleWidth = 8;

for (let i = 0; i < tentacleCount; i++) {
    const angle = (i / tentacleCount) * Math.PI * 2;
    const startX = jellyfishX + Math.cos(angle) * bodyRadius;
    const startY = jellyfishY + Math.sin(angle) * bodyRadius;

    // Tentacle base
    ctx.fillStyle = '#ff85b2';
    ctx.beginPath();
    ctx.ellipse(startX, startY, tentacleWidth, 10, angle, 0, Math.PI * 2);
    ctx.fill();

    // Tentacle tip
    ctx.fillStyle = '#ff4d80';
    ctx.beginPath();
    ctx.ellipse(startX, startY + tentacleLength, tentacleWidth * 0.7, 15, angle, 0, Math.PI * 2);
    ctx.fill();

    // Add some variation to tentacles
    ctx.fillStyle = '#ff6b9d';
    for (let j = 0; j < 3; j++) {
        const tX = startX + Math.random() * 10 - 5;
        const tY = startY + tentacleLength * (0.3 + j * 0.3) + Math.random() * 5;
        ctx.beginPath();
        ctx.arc(tX, tY, tentacleWidth * (0.8 - j * 0.2), 0, Math.PI * 2);
        ctx.fill();
    }
}

