// Stack of vinyl records
const recordColors = ['#8b4513', '#a0522d', '#cd853f', '#d2691e', '#8b4513'];
const shadowColors = ['#5d2906', '#6b3a1f', '#905c2d', '#a06d3a', '#5d2906'];

// Draw records from bottom to top
for (let i = 0; i < 5; i++) {
    const y = 250 - i * 20;
    const x = 150 + i * 5;
    const radius = 70 - i * 5;

    // Record shadow
    ctx.fillStyle = shadowColors[i];
    ctx.beginPath();
    ctx.ellipse(x + 5, y + 5, radius, radius * 0.3, 0, 0, Math.PI * 2);
    ctx.fill();

    // Record body
    ctx.fillStyle = recordColors[i];
    ctx.beginPath();
    ctx.ellipse(x, y, radius, radius, 0, 0, Math.PI * 2);
    ctx.fill();

    // Record center hole
    ctx.fillStyle = '#1a1a2e';
    ctx.beginPath();
    ctx.ellipse(x, y, radius * 0.15, radius * 0.15, 0, 0, Math.PI * 2);
    ctx.fill();

    // Groove lines
    ctx.strokeStyle = '#2a2a3e';
    ctx.lineWidth = 0.5;
    ctx.beginPath();
    for (let j = 0; j < 12; j++) {
        const angle = (j / 12) * Math.PI * 2;
        const grooveRadius = radius * 0.8;
        const startX = x + Math.cos(angle) * grooveRadius;
        const startY = y + Math.sin(angle) * grooveRadius;
        const endX = x + Math.cos(angle) * (grooveRadius * 0.2);
        const endY = y + Math.sin(angle) * (grooveRadius * 0.2);
        ctx.moveTo(startX, startY);
        ctx.lineTo(endX, endY);
    }
    ctx.stroke();
}

