    const angle2 = ((i + 1) * Math.PI) / 3;

    ctx.fillStyle = triangleColors[i % triangleColors.length];
    ctx.beginPath();
    ctx.moveTo(centerX, centerY);
    ctx.lineTo(
        centerX + Math.cos(angle1) * maxRadius,
        centerY + Math.sin(angle1) * maxRadius
    );
    ctx.lineTo(
