const drawWerewolf = () => {
  // Background - night sky
  ctx.fillStyle = '#0a0a2a';
  ctx.fillRect(0, 0, W, H);

  // Stars
  ctx.fillStyle = '#ffffff';
  for (let i = 0; i < 100; i++) {
    const x = Math.random() * W;
    const y = Math.random() * H * 0.6;
    const size = Math.random() * 2;
    ctx.fillRect(x, y, size, size);
  }

  // Moon
  ctx.fillStyle = '#f0f0f0';
  ctx.beginPath();
  ctx.arc(350, 50, 30, 0, Math.PI * 2);
  ctx.fill();

  // Ground
  ctx.fillStyle = '#2a4a2a';
  ctx.fillRect(0, 300, W, 100);

  // Werewolf body (dark gray)
  ctx.fillStyle = '#3a3a4a';
  ctx.beginPath();
  ctx.ellipse(200, 320, 80, 40, 0, 0, Math.PI * 2);
  ctx.fill();

  // Werewolf head (dark gray)
  ctx.beginPath();
  ctx.arc(250, 280, 40, 0, Math.PI * 2);
  ctx.fill();

  // Werewolf ears (dark gray)
  ctx.beginPath();
  ctx.arc(235, 250, 10, 0, Math.PI * 2);
  ctx.arc(265, 250, 10, 0, Math.PI * 2);
  ctx.fill();

  // Werewolf eyes (yellow)
  ctx.fillStyle = '#ffff00';
  ctx.beginPath();
  ctx.arc(240, 270, 6, 0, Math.PI * 2);
  ctx.arc(260, 270, 6, 0, Math.PI * 2);
  ctx.fill();

  // Werewolf nose (black)
  ctx.fillStyle = '#000000';
  ctx.beginPath();
  ctx.arc(250, 285, 5, 0, Math.PI * 2);
  ctx.fill();

  // Werewolf mouth (red)
  ctx.fillStyle = '#8b0000';
  ctx.beginPath();
  ctx.arc(250, 295, 10, 0, Math.PI);
  ctx.fill();

  // Werewolf teeth (white)
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(240, 295, 3, 8);
  ctx.fillRect(250, 295, 3, 8);
  ctx.fillRect(260, 295, 3, 8);

  // Werewolf legs (dark gray)
  ctx.fillStyle = '#3a3a4a';
  ctx.fillRect(170, 330, 15, 30);
  ctx.fillRect(230, 330, 15, 30);
  ctx.fillRect(280, 330, 15, 30);
  ctx.fillRect(330, 330, 15, 30);

  // Werewolf tail (dark gray)
  ctx.beginPath();
  ctx.moveTo(120, 320);
  ctx.lineTo(80, 300);
  ctx.lineTo(70, 310);
  ctx.lineTo(100, 330);
  ctx.closePath();
  ctx.fill();

  // Howling effect - sound waves
  ctx.strokeStyle = '#ffffff';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.arc(250, 280, 60, 0, Math.PI * 2);
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(250, 280, 80, 0, Math.PI * 2);
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(250, 280, 100, 0, Math.PI * 2);
  ctx.stroke();
};

