    const x2 = centerX + Math.cos(angle + 0.2) * (radius + 10);
    const y2 = centerY - Math.sin(angle + 0.2) * (radius + 10);

    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.stroke();
}

