function drawFlower(x, y, color) {
    // Stem
    ctx.fillStyle = '#228B22';
    ctx.fillRect(x - 3, y, 6, 60);

    // Petals
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.arc(x, y - 10, 15, 0, Math.PI * 2);
    ctx.fill();

    // Center
    ctx.fillStyle = '#FFD700';
    ctx.beginPath();
    ctx.arc(x, y - 10, 6, 0, Math.PI * 2);
    ctx.fill();
}

