// Draw falling leaves
function drawLeaves() {
    leaves.forEach(leaf => {
        ctx.fillStyle = leaf.color;
        ctx.beginPath();
        ctx.ellipse(leaf.x, leaf.y, leaf.size, leaf.size/2, 0, 0, Math.PI * 2);
        ctx.fill();

        // Update position
        leaf.y += leaf.speed;
        leaf.x += leaf.sway;

        // Reset if leaf goes off screen
        if (leaf.y > H) {
            leaf.y = -10;
            leaf.x = Math.random() * W;
        }
    });
}

